  "Search every configured module, master, transaction, report and utility.": "ക്രമീകരിച്ച മൊഡ്യൂളുകൾ, മാസ്റ്ററുകൾ, ഇടപാടുകൾ, റിപ്പോർട്ടുകൾ, ഉപകരണങ്ങൾ എന്നിവ തിരയുക.",
  "Create new records from UTF-8 CSV. Existing records are never overwritten. Limit: 500 rows, 2 MB.": "UTF-8 CSV ഉപയോഗിച്ച് പുതിയ റെക്കോർഡുകൾ സൃഷ്ടിക്കുക. നിലവിലെ റെക്കോർഡുകൾ മാറ്റില്ല. പരിധി: 500 വരികൾ, 2 MB.",
  "Upload CSV → map columns → review validation → confirm → results": "CSV അപ്‌ലോഡ് → കോളങ്ങൾ മാപ്പ് ചെയ്യുക → പരിശോധന വിലയിരുത്തുക → സ്ഥിരീകരിക്കുക → ഫലങ്ങൾ",
  "Review the errors below. Confirmation imports only valid rows; invalid rows remain excluded.": "താഴെയുള്ള പിശകുകൾ പരിശോധിക്കുക. സ്ഥിരീകരിച്ചാൽ സാധുവായ വരികൾ മാത്രം ഇറക്കുമതി ചെയ്യും; അസാധു വരികൾ ഒഴിവാക്കും.",
  "Closing pauses after the current batch. Completed rows remain imported.": "അടച്ചാൽ നിലവിലെ ബാച്ചിന് ശേഷം നിർത്തും. പൂർത്തിയായ വരികൾ ഇറക്കുമതി ചെയ്തതായി തുടരും.",
  "Choose a UTF-8 .csv file up to 2 MB.": "2 MB വരെയുള്ള UTF-8 .csv ഫയൽ തിരഞ്ഞെടുക്കുക.",
  "Review the saved record before deciding. Approval stages run in order; requesters cannot approve their own submissions.": "തീരുമാനത്തിന് മുമ്പ് സംരക്ഷിച്ച റെക്കോർഡ് പരിശോധിക്കുക. അംഗീകാര ഘട്ടങ്ങൾ ക്രമത്തിൽ നടക്കും; അപേക്ഷകർക്ക് സ്വന്തം അപേക്ഷ അംഗീകരിക്കാൻ കഴിയില്ല.",
  "Changes apply to new submissions and resubmissions. Pending approvals retain their submitted stages.": "മാറ്റങ്ങൾ പുതിയതും വീണ്ടും സമർപ്പിക്കുന്നതുമായ അപേക്ഷകൾക്ക് ബാധകമാണ്. കാത്തിരിക്കുന്ന അംഗീകാരങ്ങളുടെ ഘട്ടങ്ങൾ മാറില്ല.",
  "A comment is required for submission and every decision.": "സമർപ്പിക്കാനും ഓരോ തീരുമാനത്തിനും അഭിപ്രായം ആവശ്യമാണ്.",
