  ". The assistant summarises; it does not diagnose.": ". അസിസ്റ്റന്റ് സംഗ്രഹിക്കുന്നു; രോഗനിർണയം നടത്തുന്നില്ല.",
  ". The controls below are greyed as a courtesy — the refusal happens on the server, not here.": ". താഴെയുള്ള നിയന്ത്രണങ്ങൾ സൂചനയായി ഓഫ് ആണ്; നിരസിക്കൽ സെർവറിലാണ് നടപ്പാക്കുന്നത്.",
  "4 branches • 18,426 source records": "4 ശാഖകൾ • 18,426 ഉറവിട രേഖകൾ",
  "; administrative writes need": "; ഭരണപരമായ മാറ്റങ്ങൾക്ക് ആവശ്യമാണ്",
  "A documentation template, not clinical decision support. Prompts describe what a note of this shape usually records; they are not advice, and instruments are offered with the conditions under which they apply rather than as fields to complete.": "ഇത് രേഖപ്പെടുത്താനുള്ള മാതൃകയാണ്, ചികിത്സാ തീരുമാന സഹായമല്ല. പ്രോംപ്റ്റുകൾ സാധാരണ രേഖപ്പെടുത്തുന്ന കാര്യങ്ങൾ വിവരിക്കുന്നു; ഉപദേശമല്ല. ഉപകരണങ്ങൾ പൂരിപ്പിക്കേണ്ട ഫീൽഡുകളായല്ല, ബാധകമായ സാഹചര്യങ്ങളോടെയാണ് നൽകുന്നത്.",
  "A missing, zero or malformed limit resolves to the server's default rather than to no limit at all — which is why": "നൽകാത്തതോ പൂജ്യമോ തെറ്റായതോ ആയ പരിധിക്ക് സെർവറിന്റെ ഡിഫോൾട്ട് ബാധകമാകും; പരിധിയില്ലാതാകില്ല — അതിനാൽ",
  "A shared, schema-driven component platform for ERP masters, transactions, worklists, reports and utilities. Pages compose reusable controls instead of duplicating markup or visual rules.": "ERP മാസ്റ്ററുകൾ, ഇടപാടുകൾ, പട്ടികകൾ, റിപ്പോർട്ടുകൾ, ഉപകരണങ്ങൾ എന്നിവയ്ക്കുള്ള പങ്കിട്ട സ്കീമ അധിഷ്ഠിത ഘടക പ്ലാറ്റ്ഫോം. പേജുകൾ വീണ്ടും ഉപയോഗിക്കാവുന്ന നിയന്ത്രണങ്ങളിൽ നിന്നാണ് നിർമ്മിക്കുന്നത്.",
  "A supported level, not a submitted code. Final selection rests with the clinician or coder against current guidance, medical necessity and payer rules.": "ഇത് പിന്തുണയ്ക്കുന്ന നിലയാണ്, സമർപ്പിച്ച കോഡല്ല. നിലവിലെ മാർഗനിർദേശം, ചികിത്സാ ആവശ്യകത, പണം നൽകുന്ന കക്ഷിയുടെ നിയമങ്ങൾ എന്നിവ അനുസരിച്ച് ചികിത്സകനോ കോഡറോ അന്തിമമായി തിരഞ്ഞെടുക്കണം.",
  "A tenant setting. This tenant is configured for the UAE, where E/M levels do not apply, so the default is none.": "ഇത് ടെനന്റ് ക്രമീകരണമാണ്. ഈ ടെനന്റ് യുഎഇയ്ക്കാണ്; E/M നിലകൾ ബാധകമല്ലാത്തതിനാൽ ഡിഫോൾട്ട് ഒന്നുമില്ല.",
