  "Insert into narrative": "വിവരണത്തിൽ ചേർക്കുക",
  "Integration guide": "ഇന്റഗ്രേഷൻ ഗൈഡ്",
  "Interactive reports are limited to a configurable date range. Large historical requests should run as scheduled jobs and deliver a secure file link.": "സംവേദനാത്മക റിപ്പോർട്ടുകൾ ക്രമീകരിക്കാവുന്ന തീയതി പരിധിയിൽ പരിമിതമാണ്. വലിയ ചരിത്ര അഭ്യർത്ഥനകൾ ഷെഡ്യൂൾ ചെയ്ത ജോലികളായി പ്രവർത്തിപ്പിച്ച് സുരക്ഷിത ഫയൽ ലിങ്ക് നൽകണം.",
  "Invoice date:": "ഇൻവോയ്സ് തീയതി:",
  "Invoice summary": "ഇൻവോയ്സ് സംഗ്രഹം",
  "It is not a target. A level is supported by the work that was clinically necessary and actually done — raising an element to reach a code is the thing this panel is meant to make visible, not easier. Office and outpatient levels are selected by medical decision making": "ഇത് ലക്ഷ്യമല്ല. ചികിത്സയ്ക്ക് ആവശ്യമായതും യഥാർത്ഥത്തിൽ ചെയ്തതുമായ പ്രവർത്തനമാണ് നിലയെ പിന്തുണയ്ക്കുന്നത്. കോഡ് ലഭിക്കാൻ ഘടകങ്ങൾ ഉയർത്തുന്നത് ഈ പാനൽ വെളിപ്പെടുത്തുന്നു, എളുപ്പമാക്കുന്നില്ല. ഓഫീസ്, ഔട്ട്പേഷ്യന്റ് നിലകൾ ചികിത്സാ തീരുമാനം അടിസ്ഥാനമാക്കിയാണ് തിരഞ്ഞെടുക്കുന്നത്",
  "Keyboard shortcuts are switched off in your preferences. The list below is what they would be.": "നിങ്ങളുടെ മുൻഗണനകളിൽ കീബോർഡ് കുറുക്കുവഴികൾ ഓഫ് ആണ്. ലഭ്യമാകുന്നവയുടെ പട്ടിക താഴെ.",
  "Live": "തത്സമയം",
  "Mark as read": "വായിച്ചതായി അടയാളപ്പെടുത്തുക",
  "Mock transport — no provider was contacted.": "മാതൃകാ കൈമാറ്റം — ദാതാവുമായി ബന്ധപ്പെട്ടിട്ടില്ല.",
  "No match for “": "ഇതിന് പൊരുത്തമില്ല: “",
  "No matching options": "പൊരുത്തപ്പെടുന്ന ഓപ്ഷനുകളില്ല",
  "No provider credential is configured for this tenant, so nothing can be sent yet.": "ഈ ടെനന്റിന് ദാതാവിന്റെ പ്രവേശന വിവരങ്ങൾ ക്രമീകരിച്ചിട്ടില്ല; ഇപ്പോൾ ഒന്നും അയയ്ക്കാനാവില്ല.",
  "Not sent — this request was held back before it left the browser.": "അയച്ചില്ല — ബ്രൗസറിൽ നിന്ന് പുറത്തുപോകുന്നതിന് മുമ്പ് അഭ്യർത്ഥന തടഞ്ഞു.",
  "Nothing here": "ഇവിടെ ഒന്നുമില്ല",
  "Nothing is delivered; this is a prototype.": "ഒന്നും വിതരണം ചെയ്യുന്നില്ല; ഇത് പ്രോട്ടോടൈപ്പാണ്.",
  "Nothing on this page matches what this use case may read. There is nothing to send.": "ഈ ഉപയോഗത്തിന് വായിക്കാവുന്ന ഒന്നും ഈ പേജിലില്ല. അയയ്ക്കാൻ ഒന്നുമില്ല.",
  "Nothing selected": "ഒന്നും തിരഞ്ഞെടുത്തിട്ടില്ല",
  "Nothing to tour on this page yet.": "ഈ പേജിൽ ഇതുവരെ പര്യടനമില്ല.",
  "One configurable interface across human resources, finance, payroll, sales and supply chain.": "മാനവവിഭവം, ധനകാര്യം, ശമ്പളം, വിൽപ്പന, വിതരണ ശൃംഖല എന്നിവയ്ക്കുള്ള ഒരൊറ്റ ക്രമീകരിക്കാവുന്ന ഇന്റർഫേസ്.",
  "One screen, composed from four layers. The same engine covers every combination without a page per combination.": "നാല് തലങ്ങളിൽ നിന്നുള്ള ഒരു സ്ക്രീൻ. ഓരോ കോമ്പിനേഷനും പ്രത്യേക പേജ് ഇല്ലാതെ ഒരേ എൻജിൻ എല്ലാം കൈകാര്യം ചെയ്യുന്നു.",
  "Only the built-in mock transcriber runs in this build. The other adapters are declared with their real call shapes and have never been exercised — a session on one reports that rather than producing a transcript.": "ഈ ബിൽഡിൽ ഉൾപ്പെടുത്തിയ മാതൃകാ ട്രാൻസ്ക്രൈബർ മാത്രമേ പ്രവർത്തിക്കൂ. മറ്റു അഡാപ്റ്ററുകൾ യഥാർത്ഥ കോൾ രൂപത്തിൽ നിർവചിച്ചിട്ടുണ്ടെങ്കിലും പരീക്ഷിച്ചിട്ടില്ല; അവയിലെ സെഷൻ ട്രാൻസ്ക്രിപ്റ്റിന് പകരം അത് അറിയിക്കും.",
