  "Suggest with AI": "എഐ ഉപയോഗിച്ച് നിർദേശിക്കുക",
  "Suggestions only. Nothing is added until you click it, and a code the reply named that is not in this service's catalogue is dropped here rather than shown.": "നിർദേശങ്ങൾ മാത്രം. ക്ലിക്ക് ചെയ്യുന്നതുവരെ ഒന്നും ചേർക്കില്ല. ഈ സേവനത്തിന്റെ പട്ടികയിൽ ഇല്ലാത്ത കോഡുകൾ പ്രദർശിപ്പിക്കാതെ ഒഴിവാക്കുന്നു.",
  "Tax Invoice": "നികുതി ഇൻവോയ്സ്",
  "Tax note": "നികുതി കുറിപ്പ്",
  "Tax validated": "നികുതി പരിശോധിച്ചു",
  "Test component feedback": "ഘടക പ്രതികരണം പരിശോധിക്കുക",
  "The full page guide, the component library and the developer manual are one click away.": "പൂർണ്ണ പേജ് ഗൈഡ്, ഘടക ലൈബ്രറി, ഡെവലപ്പർ മാനുവൽ എന്നിവ ഒറ്റ ക്ലിക്കിൽ ലഭ്യമാണ്.",
  "The gateway picks the lowest priority number that is enabled, supports the session language, and has a credential. A provider that is enabled but has no key is": "ഗേറ്റ്‌വേ സജീവവും സെഷൻ ഭാഷ പിന്തുണയ്ക്കുന്നതും പ്രവേശന വിവരങ്ങളുള്ളതുമായ ഏറ്റവും കുറഞ്ഞ മുൻഗണനാ നമ്പർ തിരഞ്ഞെടുക്കുന്നു. സജീവമാണെങ്കിലും കീ ഇല്ലാത്ത ദാതാവ്",
  "This adapter has never run against its provider in this build. Treat anything below as illustrative, not as a transcript.": "ഈ ബിൽഡിൽ ഈ അഡാപ്റ്റർ ദാതാവുമായി പ്രവർത്തിച്ചിട്ടില്ല. താഴെയുള്ളത് ഉദാഹരണമാണ്, ട്രാൻസ്ക്രിപ്റ്റല്ല.",
  "This derives a level from what is already documented.": "ഇതിനകം രേഖപ്പെടുത്തിയതിൽ നിന്ന് നില നിർണയിക്കുന്നു.",
  "This document is a tax invoice issued under UAE VAT rules. Values are expressed in AED.": "ഈ രേഖ യുഎഇ വാറ്റ് നിയമങ്ങൾ പ്രകാരം നൽകിയ നികുതി ഇൻവോയ്സാണ്. തുകകൾ AED-ലാണ്.",
  "This is a clinical use case. I confirm the fields above may be sent for record": "ഇത് ക്ലിനിക്കൽ ഉപയോഗമാണ്. മുകളിലെ ഫീൽഡുകൾ ഈ രേഖയ്ക്കായി അയയ്ക്കാമെന്ന് ഞാൻ സ്ഥിരീകരിക്കുന്നു",
  "Total": "ആകെ",
  "Try again": "വീണ്ടും ശ്രമിക്കുക",
  "Unusual combination — allowed, not blocked.": "അസാധാരണ കോമ്പിനേഷൻ — അനുവദനീയമാണ്, തടഞ്ഞിട്ടില്ല.",
  "Utilization": "വിനിയോഗം",
  "Validate": "സാധൂകരിക്കുക",
  "Validation status": "സാധൂകരണ നില",
  "Verify": "പരിശോധിക്കുക",
  "Verifying and removing both reach the provider or the store, so both are audited and both count against the rate limit below. Removing cannot be undone from here — the old value is unreadable by design.": "പരിശോധനയും നീക്കലും ദാതാവിലേക്കോ സ്റ്റോറിലേക്കോ എത്തുന്നു; രണ്ടും ഓഡിറ്റ് ചെയ്യപ്പെടുകയും നിരക്കുപരിധിയിൽ കണക്കാക്കുകയും ചെയ്യും. നീക്കൽ ഇവിടെ തിരികെ ചെയ്യാനാവില്ല; പഴയ മൂല്യം വായിക്കാനാവില്ല.",
  "View analysis": "വിശകലനം കാണുക",
  "Write-only. The value is never returned by any endpoint, so it cannot be shown here or checked by eye — the last four characters and a fingerprint are what distinguish one key from another. Use": "എഴുതാൻ മാത്രം. എൻഡ്പോയിന്റുകൾ മൂല്യം തിരികെ നൽകില്ല; ഇവിടെ കാണിക്കാനോ കണ്ണുകൊണ്ട് പരിശോധിക്കാനോ കഴിയില്ല. അവസാന നാല് അക്ഷരങ്ങളും ഫിംഗർപ്രിന്റും കീകൾ തിരിച്ചറിയാൻ സഹായിക്കും. ഉപയോഗിക്കുക",
  "Your message": "നിങ്ങളുടെ സന്ദേശം",
  "ago": "മുമ്പ്",
