  "for the commands available on this page.": "ഈ പേജിൽ ലഭ്യമായ കമാൻഡുകൾക്കായി.",
  "gate. You will see exactly what is captured before anything is sent.": ". അയയ്ക്കുന്നതിനുമുമ്പ് എന്താണ് പകർത്തുന്നതെന്ന് കൃത്യമായി കാണാം.",
  "healthy": "ആരോഗ്യകരം",
  "is resolved server-side at dispatch and is never sent to a browser, so it cannot be read, replayed or edited from here — changing one is a server deployment.": "അയയ്ക്കുമ്പോൾ സെർവറിൽ നിർണയിക്കുന്നു, ബ്രൗസറിലേക്ക് അയയ്ക്കില്ല; ഇവിടെ നിന്ന് വായിക്കാനോ വീണ്ടും പ്രവർത്തിപ്പിക്കാനോ തിരുത്താനോ കഴിയില്ല. മാറ്റത്തിന് സെർവർ വിന്യാസം ആവശ്യമാണ്.",
  "is worth showing: 20 because someone chose 20 and 20 because nothing is configured look identical in the number alone.": "കാണിക്കുന്നത് ഉപകാരപ്രദമാണ്: ഒരാൾ തിരഞ്ഞെടുത്ത 20-ഉം ഒന്നും ക്രമീകരിക്കാത്തതിനാൽ വന്ന 20-ഉം സംഖ്യയായി ഒരുപോലെ കാണാം.",
