  "required sections. This measures whether the note is filled in, not whether it is clinically sufficient — and it is not a billing indicator.": "നിർബന്ധമായ വിഭാഗങ്ങൾ. കുറിപ്പ് പൂരിപ്പിച്ചോ എന്നാണ് അളക്കുന്നത്, ചികിത്സാപരമായി മതിയോ എന്നല്ല; ബില്ലിംഗ് സൂചകവുമല്ല.",
  "rows": "വരികൾ",
  "sections, ordered core → type → specialty → complaint → context. Each names its layer.": "വിഭാഗങ്ങൾ: അടിസ്ഥാനം → തരം → സ്പെഷ്യാലിറ്റി → പരാതി → സാഹചര്യം. ഓരോന്നും അതിന്റെ തലം കാണിക്കുന്നു.",
