  "will look empty. Other fields are unaffected.": "ശൂന്യമായി കാണും. മറ്റു ഫീൽഡുകളെ ബാധിക്കില്ല.",
  "working…": "പ്രവർത്തിക്കുന്നു…",
  "· audio is streamed, never stored · the transcript is not saved until you use it": "· ഓഡിയോ സ്ട്രീം ചെയ്യുന്നു, സൂക്ഷിക്കില്ല · ഉപയോഗിക്കുന്നതുവരെ ട്രാൻസ്ക്രിപ്റ്റ് സംരക്ഷിക്കില്ല",
