  "ui.document.the.clinically.relevant.history.record.only.wha.7a60920c": "ചികിത്സയ്ക്ക് പ്രസക്തമായ ചരിത്രം രേഖപ്പെടുത്തുക. വിലയിരുത്തിയ കാര്യങ്ങൾ മാത്രം രേഖപ്പെടുത്തുക.",
