  "ui.suggest.with.ai.ee9ba75a": "എഐ ഉപയോഗിച്ച് നിർദേശിക്കുക",
  "ui.assistant.not.enabled.here.select.manually.258baf78": "ഇവിടെ അസിസ്റ്റന്റ് സജീവമല്ല — സ്വയം തിരഞ്ഞെടുക്കുക",
  "ui.this.derives.a.level.from.what.is.already.documented.78e65b86": "ഇതിനകം രേഖപ്പെടുത്തിയതിൽ നിന്ന് നില നിർണയിക്കുന്നു.",
  "ui.it.is.not.a.target.a.level.is.supported.by.the.work.that.40a707bf": " ഇത് ലക്ഷ്യമല്ല. ചികിത്സയ്ക്ക് ആവശ്യമായതും യഥാർത്ഥത്തിൽ ചെയ്തതുമായ പ്രവർത്തനമാണ് നിലയെ പിന്തുണയ്ക്കുന്നത്. കോഡ് ലഭിക്കാൻ ഘടകങ്ങൾ ഉയർത്തുന്നത് ഈ പാനൽ വെളിപ്പെടുത്തുന്നു, എളുപ്പമാക്കുന്നില്ല. ഓഫീസ്, ഔട്ട്പേഷ്യന്റ് നിലകൾ ചികിത്സാ തീരുമാനം അടിസ്ഥാനമാക്കിയാണ് തിരഞ്ഞെടുക്കുന്നത് ",
  "ui.or.7175517a": "അല്ലെങ്കിൽ",
  "ui.total.time.not.by.counting.history.and.examination.bulle.4ca4c59a": "മൊത്തം സമയം; ചരിത്രവും പരിശോധനാ പോയിന്റുകളും എണ്ണിയല്ല. യുഎസ് CPT മാർഗനിർദേശം ഈ ടെനന്റിന്റെ യുഎഇ ബില്ലിംഗിന് ബാധകമല്ല.",
  "ui.patient.03989434": " രോഗി",
  "ui.total.time.on.the.date.of.the.encounter.minutes.da22cb02": "സന്ദർശന തീയതിയിലെ മൊത്തം സമയം (മിനിറ്റ്)",
  "ui.face.to.face.and.non.face.to.face.time.by.the.reporting.6df1aa8e": "ആ തീയതിയിൽ റിപ്പോർട്ട് ചെയ്യുന്ന ചികിത്സകന്റെ നേരിട്ടും അല്ലാതെയുമുള്ള സമയം. രേഖ തുറന്നിരുന്ന ദൈർഘ്യത്തിൽ നിന്ന് കണക്കാക്കരുത്.",
  "ui.min.46e2a1c0": " മിനിറ്റ് · ",
  "ui.below.the.lowest.time.band.no.level.is.supported.on.time.6475301f": "ഏറ്റവും കുറഞ്ഞ സമയപരിധിയിലും താഴെ — സമയം മാത്രം അടിസ്ഥാനമാക്കി നില പിന്തുണയ്ക്കുന്നില്ല.",
  "ui.a.supported.level.not.a.submitted.code.final.selection.r.32ace8f6": "ഇത് പിന്തുണയ്ക്കുന്ന നിലയാണ്, സമർപ്പിച്ച കോഡല്ല. നിലവിലെ മാർഗനിർദേശം, ചികിത്സാ ആവശ്യകത, പണം നൽകുന്ന കക്ഷിയുടെ നിയമങ്ങൾ എന്നിവ അനുസരിച്ച് ചികിത്സകനോ കോഡറോ അന്തിമമായി തിരഞ്ഞെടുക്കണം.",
  "ui.i.reviewed.the.clinical.content.8bdeac61": "ക്ലിനിക്കൽ ഉള്ളടക്കം ഞാൻ പരിശോധിച്ചു",
  "ui.orders.and.medication.plan.verified.fc6f12b4": "ഓർഡറുകളും മരുന്ന് പദ്ധതിയും പരിശോധിച്ചു",
  "ui.follow.up.and.safety.net.plan.verified.2e5847f1": "തുടർപരിശോധനയും സുരക്ഷാ പദ്ധതിയും പരിശോധിച്ചു",
  "ui.documentation.completeness.00bd39d9": "രേഖപ്പെടുത്തലിന്റെ പൂർത്തീകരണം",
  "ui.required.sections.this.measures.whether.the.note.is.fill.d0f288bc": " നിർബന്ധമായ വിഭാഗങ്ങൾ. കുറിപ്പ് പൂരിപ്പിച്ചോ എന്നാണ് അളക്കുന്നത്, ചികിത്സാപരമായി മതിയോ എന്നല്ല; ബില്ലിംഗ് സൂചകവുമല്ല.",
  "ui.how.this.was.composed.a455784c": "ഇത് എങ്ങനെ തയ്യാറാക്കി",
  "ui.sections.ordered.core.type.specialty.complaint.context.e.0417b2b5": " വിഭാഗങ്ങൾ: അടിസ്ഥാനം → തരം → സ്പെഷ്യാലിറ്റി → പരാതി → സാഹചര്യം. ഓരോന്നും അതിന്റെ തലം കാണിക്കുന്നു.",
