  "ui.a.tenant.setting.this.tenant.is.configured.for.the.uae.w.9f64c95a": "ഇത് ടെനന്റ് ക്രമീകരണമാണ്. ഈ ടെനന്റ് യുഎഇയ്ക്കാണ്; E/M നിലകൾ ബാധകമല്ലാത്തതിനാൽ ഡിഫോൾട്ട് ഒന്നുമില്ല.",
  "ui.scope.of.this.screen.f2f37b23": " ഈ സ്ക്രീനിന്റെ പരിധി",
  "ui.a.documentation.template.not.clinical.decision.support.p.c2723289": "ഇത് രേഖപ്പെടുത്താനുള്ള മാതൃകയാണ്, ചികിത്സാ തീരുമാന സഹായമല്ല. പ്രോംപ്റ്റുകൾ സാധാരണ രേഖപ്പെടുത്തുന്ന കാര്യങ്ങൾ വിവരിക്കുന്നു; ഉപദേശമല്ല. ഉപകരണങ്ങൾ പൂരിപ്പിക്കേണ്ട ഫീൽഡുകളായല്ല, ബാധകമായ സാഹചര്യങ്ങളോടെയാണ് നൽകുന്നത്.",
  "ui.stop.cae7d57b": "നിർത്തുക",
  "ui.recording.232c8b77": " റെക്കോർഡ് ചെയ്യുന്നു",
  "ui.paused.a7a9dc5b": "താൽക്കാലികമായി നിർത്തി",
  "ui.connecting.4b639453": "ബന്ധിപ്പിക്കുന്നു…",
  "ui.this.adapter.has.never.run.against.its.provider.in.this.ae3871c2": "ഈ ബിൽഡിൽ ഈ അഡാപ്റ്റർ ദാതാവുമായി പ്രവർത്തിച്ചിട്ടില്ല. താഴെയുള്ളത് ഉദാഹരണമാണ്, ട്രാൻസ്ക്രിപ്റ്റല്ല.",
