  "ui.verifying.and.removing.both.reach.the.provider.or.the.st.b63b3716": "പരിശോധനയും നീക്കലും ദാതാവിലേക്കോ സ്റ്റോറിലേക്കോ എത്തുന്നു; രണ്ടും ഓഡിറ്റ് ചെയ്യപ്പെടുകയും നിരക്കുപരിധിയിൽ കണക്കാക്കുകയും ചെയ്യും. നീക്കൽ ഇവിടെ തിരികെ ചെയ്യാനാവില്ല; പഴയ മൂല്യം വായിക്കാനാവില്ല.",
