  "ui.a.missing.zero.or.malformed.limit.resolves.to.the.server.fafc05f4": "നൽകാത്തതോ പൂജ്യമോ തെറ്റായതോ ആയ പരിധിക്ക് സെർവറിന്റെ ഡിഫോൾട്ട് ബാധകമാകും; പരിധിയില്ലാതാകില്ല — അതിനാൽ ",
  "ui.is.worth.showing.20.because.someone.chose.20.and.20.beca.91d7efba": " കാണിക്കുന്നത് ഉപകാരപ്രദമാണ്: ഒരാൾ തിരഞ്ഞെടുത്ത 20-ഉം ഒന്നും ക്രമീകരിക്കാത്തതിനാൽ വന്ന 20-ഉം സംഖ്യയായി ഒരുപോലെ കാണാം.",
