  "ui.speech.providers.34325dc3": "സംസാര സേവന ദാതാക്കൾ",
  "ui.priority.order.for.transcription.the.first.that.can.run.1e0d628e": "ട്രാൻസ്ക്രിപ്ഷന്റെ മുൻഗണനാക്രമം; ആദ്യം പ്രവർത്തിക്കാവുന്ന ദാതാവിനെ ഉപയോഗിക്കുന്നു.",
  "ui.configured.a3ed874e": " ക്രമീകരിച്ചത്",
  "ui.the.gateway.picks.the.lowest.priority.number.that.is.ena.1c2a2c84": "ഗേറ്റ്‌വേ സജീവവും സെഷൻ ഭാഷ പിന്തുണയ്ക്കുന്നതും പ്രവേശന വിവരങ്ങളുള്ളതുമായ ഏറ്റവും കുറഞ്ഞ മുൻഗണനാ നമ്പർ തിരഞ്ഞെടുക്കുന്നു. സജീവമാണെങ്കിലും കീ ഇല്ലാത്ത ദാതാവ് ",
  "ui.skipped.not.attempted.59189ba9": "ശ്രമിക്കാതെ ഒഴിവാക്കി",
  "ui.failing.at.call.time.would.turn.a.configuration.mistake.c05babfa": " — കോൾ സമയത്തെ പരാജയം ക്രമീകരണ പിശകിനെ പരിശോധനയ്ക്കിടയിലെ തടസ്സമാക്കും.",
  "ui.priority.5f016d6d": "മുൻഗണന ",
  "ui.key.cbc3fdcb": "കീ ····",
  "ui.no.key.a199dc8c": "കീ ഇല്ല",
  "ui.only.the.built.in.mock.transcriber.runs.in.this.build.th.99c7dabf": "ഈ ബിൽഡിൽ ഉൾപ്പെടുത്തിയ മാതൃകാ ട്രാൻസ്ക്രൈബർ മാത്രമേ പ്രവർത്തിക്കൂ. മറ്റു അഡാപ്റ്ററുകൾ യഥാർത്ഥ കോൾ രൂപത്തിൽ നിർവചിച്ചിട്ടുണ്ടെങ്കിലും പരീക്ഷിച്ചിട്ടില്ല; അവയിലെ സെഷൻ ട്രാൻസ്ക്രിപ്റ്റിന് പകരം അത് അറിയിക്കും.",
  "ui.prompts.5f2e66e6": "പ്രോംപ്റ്റുകൾ",
  "ui.ids.and.versions.the.text.stays.on.the.server.976cd4c2": "ഐഡികളും പതിപ്പുകളും. വാചകം സെർവറിൽ തുടരും.",
  "ui.registered.1804af94": " രജിസ്റ്റർ ചെയ്തത്",
  "ui.ids.and.versions.only.prompt.e8f8a0a3": "ഐഡികളും പതിപ്പുകളും മാത്രം. പ്രോംപ്റ്റ് ",
  "ui.text.982d9e3e": "വാചകം",
  "ui.is.resolved.server.side.at.dispatch.and.is.never.sent.to.0bc8d5de": " അയയ്ക്കുമ്പോൾ സെർവറിൽ നിർണയിക്കുന്നു, ബ്രൗസറിലേക്ക് അയയ്ക്കില്ല; ഇവിടെ നിന്ന് വായിക്കാനോ വീണ്ടും പ്രവർത്തിപ്പിക്കാനോ തിരുത്താനോ കഴിയില്ല. മാറ്റത്തിന് സെർവർ വിന്യാസം ആവശ്യമാണ്.",
