  "Proposes codes from this service's catalogue for the documented problem. It selects from a supplied list and cannot invent a code; nothing is applied until you accept it.": "രേഖപ്പെടുത്തിയ പ്രശ്നത്തിന് സേവനപ്പട്ടികയിൽ നിന്ന് കോഡുകൾ നിർദേശിക്കുന്നു. നൽകിയ പട്ടികയിൽ നിന്ന് തിരഞ്ഞെടുക്കുന്നു; കോഡ് സൃഷ്ടിക്കില്ല. അംഗീകരിക്കുന്നതുവരെ ഒന്നും പ്രയോഗിക്കില്ല.",
  "Proposes orders from this service's orderable catalogue for the documented problem. Selection only, never invention, and nothing is placed until you accept it.": "രേഖപ്പെടുത്തിയ പ്രശ്നത്തിന് സേവനത്തിന്റെ ഓർഡർ പട്ടികയിൽ നിന്ന് നിർദേശിക്കുന്നു. തിരഞ്ഞെടുപ്പ് മാത്രം; പുതിയത് സൃഷ്ടിക്കില്ല. അംഗീകരിക്കുന്നതുവരെ ഓർഡർ നൽകില്ല.",
