  "Older adult context: falls, cognition, function, polypharmacy, caregiver context and goals of care are surfaced.": "വയോജന സാഹചര്യം: വീഴ്ചകൾ, ബോധശേഷി, പ്രവർത്തനശേഷി, പല മരുന്നുകൾ, പരിചാരക സാഹചര്യം, പരിചരണ ലക്ഷ്യങ്ങൾ കാണിക്കുന്നു.",
  "Pregnancy context: gestational status, maternal and fetal warning signs, and medication and imaging safety are surfaced.": "ഗർഭാവസ്ഥാ സാഹചര്യം: ഗർഭനില, മാതാവിന്റെയും ഭ്രൂണത്തിന്റെയും മുന്നറിയിപ്പുകൾ, മരുന്നിന്റെയും ഇമേജിംഗിന്റെയും സുരക്ഷ കാണിക്കുന്നു.",
  "Complex multimorbidity: problem reconciliation, competing risks, medication burden and care-plan ownership are prioritised.": "സങ്കീർണ്ണ ബഹുരോഗാവസ്ഥ: പ്രശ്ന പൊരുത്തപ്പെടുത്തൽ, വിരുദ്ധ അപകടസാധ്യതകൾ, മരുന്ന് ഭാരം, പരിചരണ പദ്ധതി ഉത്തരവാദിത്തം എന്നിവയ്ക്ക് മുൻഗണന.",
  "Paediatrics with a non-paediatric patient context. Valid for adolescent and transition clinics; confirm the age ranges and permissions are right for this service.": "ശിശു സാഹചര്യത്തിന് പുറത്തുള്ള പീഡിയാട്രിക്സ്. കൗമാര, കൈമാറ്റ ക്ലിനിക്കുകളിൽ സാധുവാണ്; സേവനത്തിന്റെ പ്രായപരിധികളും അനുമതികളും സ്ഥിരീകരിക്കുക.",
  "Paediatric context outside Paediatrics. The specialty must explicitly support paediatric practice, age ranges and consent handling.": "പീഡിയാട്രിക്സിന് പുറത്തുള്ള ശിശു സാഹചര്യം. സ്പെഷ്യാലിറ്റി ശിശു ചികിത്സ, പ്രായപരിധികൾ, സമ്മത നടപടികൾ എന്നിവ വ്യക്തമായി പിന്തുണയ്ക്കണം.",
  "Pregnancy with Orthopaedics: medication and imaging safety considerations apply. This is a prompt, not a reason to withhold clinically indicated care.": "ഗർഭാവസ്ഥയും അസ്ഥിരോഗവും: മരുന്നിന്റെയും ഇമേജിംഗിന്റെയും സുരക്ഷ ബാധകം. ഇത് ഓർമ്മപ്പെടുത്തലാണ്, ആവശ്യമായ ചികിത്സ തടയാനുള്ള കാരണമല്ല.",
  "Pregnancy with Psychiatry: perinatal mental-health pathways and medication-safety considerations apply.": "ഗർഭാവസ്ഥയും മനോരോഗവും: പ്രസവകാല മാനസികാരോഗ്യ മാർഗങ്ങളും മരുന്ന് സുരക്ഷയും ബാധകം.",
  "Obstetrics & Gynaecology with a paediatric context may be adolescent gynaecology. Age, consent and privacy rules for the jurisdiction apply.": "ശിശു സാഹചര്യത്തിലെ പ്രസവ സ്ത്രീരോഗ സേവനം കൗമാര സ്ത്രീരോഗമാകാം. പ്രാദേശിക പ്രായ, സമ്മത, സ്വകാര്യതാ നിയമങ്ങൾ ബാധകം.",
  "Complex multimorbidity in Paediatrics usually implies a shared-care or long-term-conditions pathway rather than a single specialty plan.": "പീഡിയാട്രിക്സിലെ സങ്കീർണ്ണ ബഹുരോഗാവസ്ഥ സാധാരണ ഒറ്റ സ്പെഷ്യാലിറ്റി പദ്ധതിക്കുപകരം പങ്കിട്ട അല്ലെങ്കിൽ ദീർഘകാല പരിചരണ മാർഗമാണ്.",
