  "Changed by someone else": "മറ്റൊരാൾ മാറ്റി",
  "Someone updated this while you were working. Reload to see their version before saving yours.": "നിങ്ങൾ പ്രവർത്തിക്കുമ്പോൾ മറ്റൊരാൾ പുതുക്കി. നിങ്ങളുടെ പതിപ്പ് സംരക്ഷിക്കുന്നതിന് മുമ്പ് അവരുടെ പതിപ്പ് കാണാൻ വീണ്ടും ലോഡ് ചെയ്യുക.",
