  "api.message.a9180a9049d3": "ഉൽപ്പന്നവും പേജും ആവശ്യമാണ്.",
  "api.message.3afc2f7834ca": "പേരും സാധുവായ കാഴ്ച ലേഔട്ടും നൽകുക.",
  "api.message.ddb72dcbc942": "ഓരോ പേജിലും പരമാവധി 50 വ്യക്തിഗത കാഴ്ചകൾ സൂക്ഷിക്കുക.",
  "api.message.498dd0882e44": "കാഴ്ച ലഭ്യമല്ല.",
  "api.message.f4eb0cf1d3ff": "ഈ കാഴ്ച മറ്റൊരു വിൻഡോയിൽ മാറി. വീണ്ടും ശ്രമിക്കുന്നതിന് മുമ്പ് പട്ടിക പുതുക്കുക.",
