  "Only administrators can configure approval stages.": "അഡ്മിനിസ്ട്രേറ്റർമാർക്ക് മാത്രമേ അംഗീകാര ഘട്ടങ്ങൾ ക്രമീകരിക്കാനാകൂ.",
  "Configuration changed. Refresh before saving.": "ക്രമീകരണം മാറിയിരിക്കുന്നു. സംരക്ഷിക്കുന്നതിന് മുമ്പ് പുതുക്കുക.",
  "Use 1–5 named stages with at least one supported approver role.": "പേരുള്ള 1–5 ഘട്ടങ്ങളും പിന്തുണയ്ക്കുന്ന ഒരു അംഗീകാര റോളെങ്കിലും ഉപയോഗിക്കുക.",
  "Select a saved record.": "സംരക്ഷിച്ച റെക്കോർഡ് തിരഞ്ഞെടുക്കുക.",
  "Save or select an existing record first.": "ആദ്യം റെക്കോർഡ് സംരക്ഷിക്കുക അല്ലെങ്കിൽ നിലവിലുള്ളത് തിരഞ്ഞെടുക്കുക.",
  "Approval changed. Refresh before submitting.": "അംഗീകാരം മാറിയിരിക്കുന്നു. സമർപ്പിക്കുന്നതിന് മുമ്പ് പുതുക്കുക.",
  "Only the requester can resubmit this record.": "അഭ്യർത്ഥിച്ച വ്യക്തിക്ക് മാത്രമേ ഈ റെക്കോർഡ് വീണ്ടും സമർപ്പിക്കാനാകൂ.",
  "This saved version is already pending or approved.": "ഈ സംരക്ഷിച്ച പതിപ്പ് ഇതിനകം പരിഗണനയിലാണ് അല്ലെങ്കിൽ അംഗീകരിച്ചിട്ടുണ്ട്.",
  "Add a submission comment (up to 4000 characters).": "സമർപ്പണ കുറിപ്പ് ചേർക്കുക (പരമാവധി 4000 അക്ഷരങ്ങൾ).",
  "Choose 1–100 distinct records and add a decision comment.": "1–100 വ്യത്യസ്ത റെക്കോർഡുകൾ തിരഞ്ഞെടുത്ത് തീരുമാന കുറിപ്പ് ചേർക്കുക.",
  "Choose up to 100 notifications.": "പരമാവധി 100 അറിയിപ്പുകൾ തിരഞ്ഞെടുക്കുക.",
  "Unknown approval action.": "അജ്ഞാത അംഗീകാര പ്രവർത്തനം.",
  "Invalid import request.": "അസാധുവായ ഇറക്കുമതി അഭ്യർത്ഥന.",
  "Choose a product and page.": "ഉൽപ്പന്നവും പേജും തിരഞ്ഞെടുക്കുക.",
  "Your role cannot import records.": "നിങ്ങളുടെ റോളിന് റെക്കോർഡുകൾ ഇറക്കുമതി ചെയ്യാൻ അനുമതിയില്ല.",
  "A valid import identifier is required.": "സാധുവായ ഇറക്കുമതി ഐഡി ആവശ്യമാണ്.",
  "This page does not have an import definition.": "ഈ പേജിന് ഇറക്കുമതി നിർവചനം ഇല്ല.",
  "Provide 1–500 mapped rows with cells up to 4000 characters.": "1–500 മാപ്പ് ചെയ്ത വരികൾ നൽകുക; ഓരോ സെല്ലിലും പരമാവധി 4000 അക്ഷരങ്ങൾ.",
  "This import identifier has already been used.": "ഈ ഇറക്കുമതി ഐഡി നേരത്തെ ഉപയോഗിച്ചിട്ടുണ്ട്.",
  "Finish or retry earlier imports before creating another.": "പുതിയത് തുടങ്ങുന്നതിന് മുമ്പ് മുൻ ഇറക്കുമതികൾ പൂർത്തിയാക്കുക അല്ലെങ്കിൽ വീണ്ടും ശ്രമിക്കുക.",
  "Unknown import operation.": "അജ്ഞാത ഇറക്കുമതി പ്രവർത്തനം.",
  "Import not available.": "ഇറക്കുമതി ലഭ്യമല്ല.",
  "The import definition is no longer available.": "ഇറക്കുമതി നിർവചനം ഇനി ലഭ്യമല്ല.",
  "A product, page and saved record are required.": "ഉൽപ്പന്നവും പേജും സംരക്ഷിച്ച റെക്കോർഡും ആവശ്യമാണ്.",
  "Attachment is no longer available.": "അറ്റാച്ച്മെന്റ് ഇനി ലഭ്യമല്ല.",
