  "Operation identifier was already used for another change.": "ഈ പ്രവർത്തന ഐഡി മറ്റൊരു മാറ്റത്തിന് ഉപയോഗിച്ചിട്ടുണ്ട്.",
  "Enter a comment of 1–4000 characters.": "1–4000 അക്ഷരങ്ങളുള്ള കുറിപ്പ് നൽകുക.",
