  "This record is already linked.": "ഈ റെക്കോർഡ് ഇതിനകം ബന്ധിപ്പിച്ചിട്ടുണ്ട്.",
  "This demo supports 100 links per record.": "ഈ ഡെമോയിൽ ഓരോ റെക്കോർഡിലും 100 ബന്ധങ്ങൾ അനുവദിക്കുന്നു.",
