  "Approval request is too large or invalid.": "അംഗീകാര അഭ്യർത്ഥന വളരെ വലുതാണ് അല്ലെങ്കിൽ അസാധുവാണ്.",
  "Your session ended.": "നിങ്ങളുടെ സെഷൻ അവസാനിച്ചു.",
