  "Import exceeds the service request limit.": "ഇറക്കുമതി സേവന അഭ്യർത്ഥന പരിധി കവിയുന്നു.",
  "Import status could not be confirmed. Resume the import to check completed rows.": "ഇറക്കുമതി നില സ്ഥിരീകരിക്കാനായില്ല. പൂർത്തിയായ വരികൾ പരിശോധിക്കാൻ ഇറക്കുമതി തുടരുക.",
  "Invalid request or attachment larger than 2 MB.": "അഭ്യർത്ഥന അസാധുവാണ് അല്ലെങ്കിൽ അറ്റാച്ച്മെന്റ് 2 MB-ൽ കൂടുതലാണ്.",
  "Save or select an existing record before using these panels.": "ഈ പാനലുകൾ ഉപയോഗിക്കുന്നതിന് മുമ്പ് റെക്കോർഡ് സംരക്ഷിക്കുക അല്ലെങ്കിൽ നിലവിലുള്ളത് തിരഞ്ഞെടുക്കുക.",
  "That related record was not found on the selected page.": "തിരഞ്ഞെടുത്ത പേജിൽ ബന്ധപ്പെട്ട റെക്കോർഡ് കണ്ടെത്തിയില്ല.",
  "Record panels could not be saved. Retry the operation.": "റെക്കോർഡ് പാനലുകൾ സംരക്ഷിക്കാനായില്ല. വീണ്ടും ശ്രമിക്കുക.",
  "Invalid view request.": "അസാധുവായ കാഴ്ച അഭ്യർത്ഥന.",
  "Could not save personal views.": "വ്യക്തിഗത കാഴ്ചകൾ സംരക്ഷിക്കാനായില്ല.",
  "Select 1–100 record IDs.": "1–100 റെക്കോർഡ് ഐഡികൾ തിരഞ്ഞെടുക്കുക.",
  "Could not archive records.": "റെക്കോർഡുകൾ ആർക്കൈവ് ചെയ്യാനായില്ല.",
  "A search needs a pageId.": "തിരയാൻ pageId ആവശ്യമാണ്.",
  "That worklist does not exist.": "ഈ പ്രവർത്തന പട്ടിക നിലവിലില്ല.",
  "Invalid record address.": "അസാധുവായ റെക്കോർഡ് വിലാസം.",
  "An edit needs a page and a record.": "തിരുത്താൻ പേജും റെക്കോർഡും ആവശ്യമാണ്.",
  "An edit needs a column.": "തിരുത്താൻ കോളം ആവശ്യമാണ്.",
  "That record is not on this list.": "ഈ റെക്കോർഡ് ഈ പട്ടികയിൽ ഇല്ല.",
  "Someone changed this while you were editing.": "നിങ്ങൾ തിരുത്തുന്നതിനിടെ മറ്റൊരാൾ ഇത് മാറ്റി.",
  "An export record needs a pageId.": "കയറ്റുമതി റെക്കോർഡിന് pageId ആവശ്യമാണ്.",
  "A saved view needs a pageId and filters.": "സംരക്ഷിച്ച കാഴ്ചയ്ക്ക് pageId-യും ഫിൽട്ടറുകളും ആവശ്യമാണ്.",
  "That saved view is not available.": "ആ സംരക്ഷിച്ച കാഴ്ച ലഭ്യമല്ല.",
  "No credential is configured for this tenant.": "ഈ ടെനന്റിന് ക്രെഡൻഷ്യൽ ക്രമീകരിച്ചിട്ടില്ല.",
  "A credential is required.": "ക്രെഡൻഷ്യൽ ആവശ്യമാണ്.",
  "That does not look like a provider key.": "ഇത് സാധുവായ പ്രൊവൈഡർ കീ പോലെ തോന്നുന്നില്ല.",
  "Unknown credential scope.": "അജ്ഞാത ക്രെഡൻഷ്യൽ പരിധി.",
  "A credential cannot be set through /ai/config.": "/ai/config വഴി ക്രെഡൻഷ്യൽ ക്രമീകരിക്കാനാകില്ല.",
  "Unknown prompt.": "അജ്ഞാത പ്രോംപ്റ്റ്.",
