  "Nothing to send.": "അയയ്ക്കാൻ ഒന്നുമില്ല.",
  "No speech provider is available for this language.": "ഈ ഭാഷയ്ക്ക് സ്പീച്ച് പ്രൊവൈഡർ ലഭ്യമല്ല.",
