  "This view changed in another window. Reload the list before trying again.": "ഈ കാഴ്ച മറ്റൊരു വിൻഡോയിൽ മാറി. വീണ്ടും ശ്രമിക്കുന്നതിന് മുമ്പ് പട്ടിക പുതുക്കുക.",
