  "draft.policyHelp": "ഈ നിയമങ്ങൾ ഈ ടെനന്റിലെയും ആപ്ലിക്കേഷനിലെയും എല്ലാവർക്കും ബാധകമാണ്. ഡ്രാഫ്റ്റുകൾ ബ്രൗസറിലല്ല, സേവനത്തിലാണ് സൂക്ഷിക്കുന്നത്. സംഭരണം പ്രവർത്തനരഹിതമാക്കുന്നത് നിലവിലെ ഡ്രാഫ്റ്റുകൾ ഇല്ലാതാക്കും. കുറഞ്ഞ സൂക്ഷിക്കൽ കാലയളവും പുതിയ ഒഴിവാക്കലുകളും നിലവിലെ ഡ്രാഫ്റ്റുകൾക്കും ബാധകമാണ്.",
