  "draft.exclusionHelp": "ഓരോ വരിയിലും ഒരു ഫീൽഡ്, ഉദാഹരണത്തിന് email, comment അല്ലെങ്കിൽ lines.notes. പേരുകൾ എല്ലാ തലങ്ങളിലും ബാധകമാണ്; ഡോട്ട് ചേർത്ത പാതകൾ പ്രത്യേക നെസ്റ്റഡ് ഫീൽഡുകൾക്കാണ്. അംഗീകാര കുറിപ്പുകൾ സൂക്ഷിക്കാതിരിക്കാൻ comment ഒഴിവാക്കുക.",
