  "catalog.help.cards": "കാർഡുകൾ, ഗ്രിഡുകൾ, സ്ഥിതിവിവരക്കണക്കുകൾ, മൂല്യങ്ങൾ എന്നിവ ചേർക്കുക. തിരഞ്ഞെടുത്ത ലോക്കേലിൽ തുകകൾ ഫോർമാറ്റ് ചെയ്യുക.",
