  "catalog.help.feedback": "open/onClose ഉപയോഗിച്ച് ഓവർലേ നിയന്ത്രിക്കുക. പരാജയങ്ങൾക്ക് വീണ്ടെടുക്കൽ പ്രവർത്തനങ്ങൾ നൽകുകയും വീണ്ടും ശ്രമിക്കുമ്പോൾ ഇൻപുട്ട് നിലനിർത്തുകയും ചെയ്യുക.",
  "catalog.help.inline": "onCommit അസിങ്ക്രണസ് ആകാം, പിശക് നൽകാനും കഴിയും. സംരക്ഷിക്കുന്നതിന് മുമ്പ് പരിശോധിക്കുക; അനുവദിച്ച സ്റ്റാറ്റസ് മാറ്റങ്ങൾ പരിമിതപ്പെടുത്തുക.",
  "catalog.help.formPatterns": "പങ്കിട്ട കൺട്രോളുകൾ ചേർത്ത് പരിശോധിച്ച ഫോം ഉണ്ടാക്കുക. ലോക്കൽ സബ്മിറ്റ് കോൾബാക്കിന് പകരം അംഗീകൃത റെക്കോർഡ് അഡാപ്റ്റർ ഉപയോഗിക്കുക.",
  "catalog.help.dataPatterns": "DataTable-ന് നിരകൾ, കോളങ്ങൾ, തിരഞ്ഞെടുപ്പ്, ക്രമീകരണം, കോൾബാക്കുകൾ നൽകുക. അനുമതികളും സ്ഥിരസംഭരണവും വിളിക്കുന്ന ആപ്ലിക്കേഷന്റെ ചുമതലയാണ്.",
  "catalog.help.billing": "പങ്കിട്ട സംഖ്യാ ഇൻപുട്ടുകളും ഡാറ്റാ പ്രദർശന ഘടകങ്ങളും ഉപയോഗിച്ച് ഇനങ്ങളും ആകെ തുകയും ഉണ്ടാക്കുക. ഇത് സമ്പൂർണ്ണ ഇൻവോയ്സ് സേവനമല്ല.",
  "catalog.help.localization": "ഷെൽ LocalizationProvider നൽകുന്നു. ലേബലുകൾക്കും ദിശയ്ക്കും പ്രദർശനത്തിനും അതിന്റെ വിവർത്തകൻ ഉപയോഗിക്കുക. ഐഡന്റിഫയറുകളോ API മൂല്യങ്ങളോ വിവർത്തനം ചെയ്യരുത്.",
  "catalog.example.TextDemo": "value, onChange എന്നിവ ഫോം സ്റ്റേറ്റുമായി ബന്ധിപ്പിക്കുക. required, hint, error, disabled എന്നിവ പരിശോധനയും ലഭ്യതയും നിയന്ത്രിക്കുന്നു.",
  "catalog.example.ValidationDemo": "value, onChange എന്നിവ ഫോം സ്റ്റേറ്റുമായി ബന്ധിപ്പിക്കുക. required, hint, error, disabled എന്നിവ പരിശോധനയും ലഭ്യതയും നിയന്ത്രിക്കുന്നു.",
