  "catalog.example.ReferenceDemo": "value, onChange എന്നിവ ഫോം സ്റ്റേറ്റുമായി ബന്ധിപ്പിക്കുക. required, hint, error, disabled എന്നിവ പരിശോധനയും ലഭ്യതയും നിയന്ത്രിക്കുന്നു.",
