  "catalog.example.CalendarDemo": "ISO തീയതിയും ലോക്കൽ സമയവും സ്റ്റേറ്റിൽ സൂക്ഷിക്കുക. min/max പരിധികൾ നൽകുക; സേവനത്തിൽ സമയമേഖല തീരുമാനിക്കുക.",
  "catalog.example.CardsDemo": "കാർഡുകൾ, ഗ്രിഡുകൾ, സ്ഥിതിവിവരക്കണക്കുകൾ, മൂല്യങ്ങൾ എന്നിവ ചേർക്കുക. തിരഞ്ഞെടുത്ത ലോക്കേലിൽ തുകകൾ ഫോർമാറ്റ് ചെയ്യുക.",
