  "catalog.example.StatusDemo": "കാർഡുകൾ, ഗ്രിഡുകൾ, സ്ഥിതിവിവരക്കണക്കുകൾ, മൂല്യങ്ങൾ എന്നിവ ചേർക്കുക. തിരഞ്ഞെടുത്ത ലോക്കേലിൽ തുകകൾ ഫോർമാറ്റ് ചെയ്യുക.",
  "catalog.example.ValuesDemo": "കാർഡുകൾ, ഗ്രിഡുകൾ, സ്ഥിതിവിവരക്കണക്കുകൾ, മൂല്യങ്ങൾ എന്നിവ ചേർക്കുക. തിരഞ്ഞെടുത്ത ലോക്കേലിൽ തുകകൾ ഫോർമാറ്റ് ചെയ്യുക.",
  "catalog.example.TableDemo": "സ്ഥിരം, വരയിട്ട, അതിരുള്ള, ഒതുക്കമുള്ള പട്ടികകൾക്കായി പട്ടിക ഘടകങ്ങൾ ഉപയോഗിക്കുക. DataTable തിരഞ്ഞെടുപ്പ്, ക്രമീകരണം, എഡിറ്റിംഗ് എന്നിവ നൽകുന്നു.",
