  "template.componentHelp": "പേജുകൾ പങ്കിട്ട ഫീൽഡുകൾ, കാർഡുകൾ, പട്ടികകൾ, കലണ്ടറുകൾ, ഓവർലേകൾ, വീണ്ടെടുക്കൽ സന്ദേശങ്ങൾ എന്നിവ ഉപയോഗിക്കുന്നു. ക്രമീകരണം ലേബലുകളും വിഭാഗങ്ങളും പ്രവർത്തനങ്ങളും നൽകുന്നു.",
  "template.preferenceHelp": "ആപ്ലിക്കേഷൻ തീം, ഫോണ്ട്, സാന്ദ്രത, ഭാഷ, ഫോർമാറ്റിംഗ്, ലേഔട്ട് മുൻഗണനകൾ നൽകുന്നു. പ്രിവ്യൂ കൺട്രോളുകൾ സംരക്ഷിച്ച മുൻഗണനകൾ മാറ്റില്ല.",
