  "template.help.logistics": "ഇൻവെന്ററി അല്ലെങ്കിൽ ഗതാഗതത്തിനായി നീക്കങ്ങളുടെ വിവരങ്ങളും ഇനങ്ങളും പ്രവർത്തന നിലയും തയ്യാറാക്കുക.",
  "template.help.finance": "സ്ഥിരതയുള്ള സാമ്പത്തിക എൻട്രി, ആകെ തുക, പൊരുത്തപ്പെടുത്തൽ, സ്റ്റേറ്റ്മെന്റ് ലേഔട്ടുകൾ ഉപയോഗിക്കുക. പോസ്റ്റിംഗ് നിയമങ്ങൾ അക്കൗണ്ടിംഗ് സേവനത്തിന്റേതാണ്.",
