  "template.clinical.granted": "അനുവദിച്ചു",
  "template.clinical.guideApi": "ClinicalPatientWorkspace-ന് ClinicalTemplateAdapter നൽകുക. ഡെമോ അഡാപ്റ്റർ അംഗീകൃത clinical-templates എൻഡ്പോയിന്റ് ഉപയോഗിക്കുന്നു; വിവരങ്ങളും ഫോം മെറ്റാഡാറ്റയും API-യിൽ നിന്നാണ്.",
  "template.clinical.guideComponents": "പങ്കിട്ട കാർഡുകൾ, ഫീൽഡുകൾ, പട്ടികകൾ, ടാബുകൾ, പാനലുകൾ, ഡയലോഗുകൾ, തീയതി/സമയ നിയന്ത്രണങ്ങൾ എന്നിവയാണ് മൂന്ന് രോഗി പേജുകളും നിർമ്മിക്കുന്നത്.",
  "template.clinical.guideFlow": "രോഗികളെ തിരയുക, ദ്രുത വിവരങ്ങൾ പരിശോധിക്കുക, തുടർന്ന് രേഖയോ സമഗ്ര കാഴ്ചയോ തുറക്കുക. നാവിഗേഷനിൽ രോഗിയുടെ തിരിച്ചറിയൽ നിലനിർത്തുന്നു.",
  "template.clinical.guideLimits": "ഡെമോ പരിചരണ വിവരങ്ങൾ സാങ്കൽപ്പികമാണ്. യഥാർത്ഥ ക്ലിനിക്കൽ തീരുമാനങ്ങൾ, അർഹത, ഫയൽ സംഭരണം, അറിയിപ്പുകൾ എന്നിവയ്ക്ക് അംഗീകൃത സേവനങ്ങൾ വേണം. സംരക്ഷിക്കാത്ത മൂല്യങ്ങൾ മെമ്മറിയിൽ തുടരും; രഹസ്യ ഡ്രാഫ്റ്റുകൾ സ്വയം സൂക്ഷിക്കില്ല.",
  "template.clinical.guidePreferences": "പങ്കിട്ട ഷെൽ ഭാഷ, ദിശ, തീം, ഫോണ്ട്, സാന്ദ്രത, ഫോർമാറ്റിംഗ്, ഫോം നാവിഗേഷൻ മുൻഗണനകൾ നൽകുന്നു. പ്രിവ്യൂ നിയന്ത്രണങ്ങൾ ടെനന്റ് നയം മാറ്റുന്നില്ല.",
  "template.clinical.guideSave": "സംരക്ഷിക്കുമ്പോൾ ഫീൽഡുകൾ, ആവർത്തിച്ച തിരിച്ചറിയൽ, രേഖാപതിപ്പുകൾ എന്നിവ പരിശോധിക്കുന്നു; വീണ്ടും ശ്രമിക്കുമ്പോൾ അതേ പ്രവർത്തന ID ഉപയോഗിക്കുന്നു. വൈരുദ്ധ്യമുണ്ടെങ്കിൽ പുതിയ രേഖ വ്യക്തമായി പരിശോധിക്കുക.",
