  "template.clinical.noWholeWords": "മുഴുവൻ വാക്കുമായി പൊരുത്തമില്ല. പൂർണ്ണ വാക്ക് നൽകുക, അല്ലെങ്കിൽ ഭാഗിക വിവരത്തിന് അനുയോജ്യമായ ഫീൽഡ് ഉപയോഗിക്കുക.",
  "template.clinical.relaxFilters": "തിരിച്ചറിയൽ നമ്പറിലെ തെറ്റുകൾ പരിശോധിക്കുക അല്ലെങ്കിൽ ഒരു ഫിൽട്ടർ നീക്കുക. പേരിട്ട ഫീൽഡുകളിൽ ഭാഗിക വിവരങ്ങൾ തിരയാം.",
