  "catalog.reference.theme-studio": "തീം മാറ്റി നിലവിലെ മുൻഗണനകളോടെ പൊതുഘടകങ്ങൾ പരിശോധിക്കുക.",
  "catalog.reference.accessibility": "വായനയും ചലനവും ക്രമീകരിച്ച് ആക്‌സസിബിലിറ്റി ഫോം ഉദാഹരണം പരിശോധിക്കുക.",
  "catalog.reference.page-catalog": "നിങ്ങളുടെ അക്കൗണ്ടിൽ ലഭ്യമായ പേജുകൾ തിരഞ്ഞ് തുറക്കുക.",
  "catalog.reference.component-contracts": "ഓരോ പൊതുഘടകത്തിന്റെയും സോഴ്‌സ്, പ്രവർത്തനം, സംയോജന ഉദാഹരണം എന്നിവ കാണുക.",
  "catalog.reference.keyboard-shortcuts": "ആപ്ലിക്കേഷൻ ഉപയോഗിക്കുന്ന അതേ പട്ടികയിൽ നിന്നുള്ള കീബോർഡ് നിർദ്ദേശങ്ങൾ.",
  "catalog.reference.integration-guide": "ഷെൽ പകർത്താതെയും നയങ്ങൾ മറികടക്കാതെയും പുനരുപയോഗിക്കാവുന്ന പേജുകൾ ബന്ധിപ്പിക്കുക.",
  "catalog.reference.livePreferences": "ഈ നിയന്ത്രണങ്ങൾ നിങ്ങളുടെ യഥാർഥ മുൻഗണനകൾ മാറ്റുന്നു. അഡ്മിനിസ്ട്രേറ്റർ ലോക്കുകൾ ബാധകമാണ്.",
  "catalog.reference.accessibilityCheck": "Tab, Shift+Tab ഉപയോഗിച്ച് നിയന്ത്രണങ്ങൾക്കിടയിൽ നീങ്ങുക. ഫോക്കസ്, ലേബലുകൾ, പിശക് അറിയിപ്പുകൾ പരിശോധിക്കുക.",
  "catalog.reference.focusHelp": "ലേബലും സഹായവിവരവും ഈ ഫീൽഡുമായി ബന്ധിപ്പിച്ചിരിക്കുന്നു.",
  "catalog.reference.accessibilityLimit": "ഈ ഉദാഹരണം നേരിട്ടുള്ള പരിശോധനയ്ക്ക് സഹായിക്കുന്നു; ഇത് ആക്‌സസിബിലിറ്റി സർട്ടിഫിക്കേഷൻ അല്ല.",
  "catalog.reference.contract": "എക്‌സ്‌പോർട്ട് ചെയ്ത ഘടകവും TypeScript props-ഉം ഉപയോഗിക്കുക. വിവർത്തനം ചെയ്ത ലേബലുകൾ, ആക്‌സസിബിൾ പേരുകൾ, മുൻഗണനകൾ, പ്രവർത്തന ഹാൻഡ്‌ലറുകൾ എന്നിവ നൽകുക.",
  "catalog.reference.shortcutScope": "⌘ എന്നത് macOS-ൽ Command, മറ്റ് സിസ്റ്റങ്ങളിൽ Ctrl ആണ്. വർക്ക്‌സ്‌പേസ് ഷോർട്ട്കട്ടുകൾക്ക് ഡെസ്‌ക്‌ടോപ്പ് പിന്തുണ വേണം. ഷോർട്ട്കട്ടുകൾ ഓഫാക്കിയാലും സാധാരണ കീബോർഡ് നാവിഗേഷൻ ലഭ്യമാണ്.",
  "catalog.reference.providers": "ആപ്ലിക്കേഷൻ പ്രൊവൈഡറുകൾ",
  "catalog.reference.providersHelp": "നിലവിലുള്ള ഓതന്റിക്കേഷൻ, പ്രോഡക്റ്റ്, നാവിഗേഷൻ, ലോക്കലൈസേഷൻ, ERP പ്രൊവൈഡറുകൾ ഉപയോഗിക്കുക. UI ഘടകങ്ങളെ API ക്ലയന്റുകളിൽ നിന്ന് വേർതിരിക്കുക.",
  "catalog.reference.preferencesHelp": "പുനരുപയോഗിക്കാവുന്ന വർക്ക്‌സ്‌പേസുകൾക്ക് preferences, preferencePolicy, preferencesAvailable, onPreferenceChange നൽകുക. ലോക്ക് ചെയ്ത നയമൂല്യങ്ങൾ പ്രാദേശിക തിരഞ്ഞെടുപ്പുകളേക്കാൾ മുൻഗണന നേടും.",
  "catalog.reference.integrationSteps": "ടെംപ്ലേറ്റ് തിരഞ്ഞെടുത്ത് TypeScript ഉദാഹരണം തുറന്ന് ഡെമോ അഡാപ്റ്ററിന് പകരം ഓതന്റിക്കേറ്റഡ് API അഡാപ്റ്റർ നൽകുക. റിലീസിന് മുമ്പ് വാലിഡേഷൻ, വൈരുധ്യങ്ങൾ, വീണ്ടെടുക്കൽ, അനുമതികൾ, മുൻഗണന ലോക്കുകൾ എന്നിവ പരിശോധിക്കുക.",
  "preferences.recordLayout.help": "റെയിൽ വിഭാഗങ്ങൾ ഫോമിന്റെ വശത്ത് കാണിക്കുന്നു. ടാബുകൾ ഒരേസമയം ഒരു വിഭാഗം കാണിക്കുന്നു. വിസാർഡിൽ മുമ്പത്തെയും അടുത്തതുമായ ഘട്ടങ്ങളിലേക്ക് പോകാം. രോഗിയുടെ റെക്കോർഡ് ഉൾപ്പെടെ പുതിയതും കാണുന്നതും തിരുത്തുന്നതുമായ ഫോമുകൾക്ക് ഇത് ബാധകമാണ്.",
  "preferences.spacing.title": "അകലവും കോണുകളും",
  "preferences.spacing.help": "പങ്കിട്ട പേജ് ഘടകങ്ങൾക്ക് ഒതുങ്ങിയതോ സൗകര്യപ്രദമായതോ വിശാലമായതോ ആയ അകലവും കോണുകളുടെ വളവും തിരഞ്ഞെടുക്കുക. രോഗിയുടെ റെക്കോർഡും ഈ മുൻഗണനകൾ ഉപയോഗിക്കുന്നു.",
  "template.group.registry": "രജിസ്ട്രി ഡിസൈൻ കൂട്ടം",
