  "template.clinic.paymentHint": "ഡെമോ എൻട്രികൾ മാത്രം; പണം കൈമാറുന്നില്ല. ഭാഗിക പേയ്മെന്റ് ലഭ്യമാണ്. കാർഡ്, ട്രാൻസ്ഫർ എന്നിവയ്ക്ക് റഫറൻസ് വേണം. റീഫണ്ടിന് കാരണം വേണം; ഒരു പേയ്മെന്റിന്റെ മുഴുവൻ തുകയും തിരിച്ചുനൽകും.",
