  "template.clinic.error.payment": "ബാക്കി തുകയ്ക്കുള്ളിൽ പൂജ്യത്തേക്കാൾ വലിയ തുകയും ആവശ്യമായ റഫറൻസും നൽകുക.",
  "template.clinic.error.refund": "ഈ പേയ്മെന്റ് റീഫണ്ട് ചെയ്യാനാവില്ല. ചരിത്രം പരിശോധിച്ച് കാരണം നൽകുക.",
  "template.clinic.error.void": "പേയ്മെന്റ് ചരിത്രമില്ലാത്ത ബിൽ മാത്രമേ റദ്ദാക്കാനാകൂ. കാരണം ആവശ്യമാണ്.",
  "template.clinic.error.storage": "ലെഡ്ജർ സേവ് ചെയ്യാനായില്ല. അതേ പ്രവർത്തനം വീണ്ടും ശ്രമിക്കുക.",
  "template.clinic.guideFlow": "പേജുകളുടെ പട്ടികയിൽ ക്ലിനിക് ബില്ലിങ്ങിന് കീഴിൽ രോഗിയെ തിരഞ്ഞെടുത്താൽ ആ രോഗിയുടെ ബില്ലിങ് പുതിയ ടാബിൽ തുറക്കും. ഇൻവോയ്സുകളും പേയ്മെന്റുകളും തുറന്ന് ബിൽ കാണുക തിരഞ്ഞെടുക്കുക. ഇനങ്ങൾ, ഇൻഷുറൻസ്, രസീതുകൾ, മുൻ പതിപ്പുകൾ കാണാം. പണമടയ്ക്കാത്ത നൽകിയ ബില്ലിലെ അളവ്, കിഴിവ്, ഇൻഷുറൻസ്, കുറിപ്പുകൾ എന്നിവ കാരണം നൽകി തിരുത്താം. API നിലവിലെ നിരക്കുകളിൽ വീണ്ടും കണക്കാക്കി മുൻ പതിപ്പ് സൂക്ഷിക്കും. റീഫണ്ട് ഉൾപ്പെടെ പണമടച്ച ചരിത്രമുള്ള ബിൽ തിരുത്താനാവില്ല. സംഘർഷമുണ്ടെങ്കിൽ പുതിയ ലെഡ്ജർ ലോഡ് ചെയ്ത് പരിശോധിക്കുക. താൽക്കാലിക പരാജയത്തിൽ തിരുത്തലുകൾ നിലനിൽക്കും; മടങ്ങുമ്പോൾ ഉപേക്ഷിക്കൽ സ്ഥിരീകരിക്കണം.",
  "template.clinic.guideIntegration": "TypeScript ഉദാഹരണത്തിലെ വർക്ക്‌സ്‌പേസും അഡാപ്റ്ററുകളും ഉപയോഗിക്കുക. ആധികാരിക ഡെമോ API രോഗികളുടെ CSV വായിക്കുകയും പ്രത്യേക ബില്ലിംഗ് CSV എഴുതുകയും ചെയ്യുന്നു. മറ്റൊരു ആപ്പിനായി അഡാപ്റ്ററുകൾ മാറ്റുക.",
  "template.clinic.guidePreferences": "ലേഔട്ട്, തീം, ഫോണ്ട്, സാന്ദ്രത, പട്ടികകൾ, തീയതി, സംഖ്യകൾ എന്നിവ ടെനന്റ് നയങ്ങൾ പാലിക്കുന്നു. ലെഡ്ജർ കറൻസി API നൽകുന്നു; പ്രദർശന മുൻഗണന അത് മാറ്റുന്നില്ല.",
  "template.clinic.guideRecovery": "പരിഹരിക്കാവുന്ന പിശകുകളിൽ വിവരങ്ങൾ നിലനിൽക്കും. വീണ്ടും ശ്രമിക്കുമ്പോൾ അതേ പ്രവർത്തന ഐഡി ഉപയോഗിക്കുന്നു. തർക്കമുണ്ടെങ്കിൽ പുതിയ ലെഡ്ജർ ലോഡ് ചെയ്ത് വിവരങ്ങൾ പരിശോധിക്കുക. ബ്രൗസർ അടച്ച ശേഷമുള്ള ഡ്രാഫ്റ്റ് പുനഃസ്ഥാപനം ലഭ്യമല്ല.",
  "template.clinic.guideLimits": "ഒരു പ്രോസസ്സിലുള്ള സാങ്കൽപ്പിക ഡെമോ: യഥാർഥ കാർഡ് പ്രോസസ്സിംഗ്, ഇൻഷുറൻസ് സമർപ്പണം, നികുതി സർട്ടിഫിക്കേഷൻ, മരുന്ന് വിതരണം, അക്കൗണ്ടിംഗ് പോസ്റ്റിംഗ് എന്നിവയില്ല. മുഴുവൻ പേയ്മെന്റാണ് റീഫണ്ട് ചെയ്യുന്നത്; നൽകിയ ബിൽ തിരുത്താനാവില്ല.",
  "template.clinic.event.order": "പ്രിസ്ക്രിപ്ഷനുകൾ ഓർഡറാക്കി",
