  "template.triage.conflict": "ഈ വിലയിരുത്തൽ മാറി. പുതിയത് ലോഡ് ചെയ്ത് വീണ്ടും സേവ് ചെയ്യുന്നതിന് മുമ്പ് പരിശോധിക്കുക.",
  "template.triage.completedLocked": "പൂർത്തിയായ വിലയിരുത്തലുകൾ ലോക്ക് ചെയ്തിരിക്കുന്നു. മാറ്റങ്ങൾ രേഖപ്പെടുത്താൻ പുതിയത് തുടങ്ങുക.",
  "template.triage.notFound": "വിലയിരുത്തൽ കണ്ടെത്തിയില്ല.",
  "template.triage.storage": "വിലയിരുത്തൽ സേവ് ചെയ്യാനായില്ല. വീണ്ടും ശ്രമിക്കാൻ വിവരങ്ങൾ നിലനിൽക്കുന്നു.",
  "template.triage.event.saved": "ഡ്രാഫ്റ്റ് ഡെമോ APIയിൽ സേവ് ചെയ്തു",
  "template.triage.event.completed": "ട്രയേജ് വിലയിരുത്തൽ പൂർത്തിയായി",
  "template.triage.guideFlow": "രോഗിയെ തിരഞ്ഞെടുക്കുക. പരാതി, അളവുകൾ, അലർജി, മുൻഗണന, അടുത്ത വിഭാഗം എന്നിവ നൽകുക. ഡ്രാഫ്റ്റ് സേവ് ചെയ്യുക അല്ലെങ്കിൽ പരിശോധിച്ച് പൂർത്തിയാക്കുക. മുൻ വിലയിരുത്തലുകൾ തുറക്കാം; പുതിയത് ശൂന്യമായ അളവുകളോടെ തുടങ്ങും.",
  "template.triage.guideIntegration": "TypeScript ഉദാഹരണത്തിലെ ട്രയേജ്, രോഗി അഡാപ്റ്ററുകളോടെ ClinicalTriageWorkspace ഉപയോഗിക്കുക. ആധികാരിക API രോഗി CSV വായിക്കുകയും വിലയിരുത്തലുകൾ ടെനന്റ്/ആപ്പ്/രോഗി അടിസ്ഥാനത്തിലുള്ള പ്രത്യേക CSVയിൽ സേവ് ചെയ്യുകയും ചെയ്യുന്നു.",
  "template.triage.guidePreferences": "നമ്പറുള്ള റെക്കോർഡ് നാവിഗേഷനിലൂടെ പരാതി, സുരക്ഷ, ജീവസൂചകങ്ങൾ, കൈമാറ്റം എന്നിവ തിരഞ്ഞെടുക്കുക. ഒരു വിഭാഗവും ട്രയാജ് സംഗ്രഹവും ഒരുമിച്ച് കാണാം. ഡ്രാഫ്റ്റ് സംരക്ഷിക്കലും പൂർത്തിയാക്കലും ലഭ്യമാണ്. ടാബുകളും വിസാർഡും പ്രാബല്യത്തിലുള്ള മുൻഗണനകൾ പാലിക്കും. വിവരങ്ങളും ഓപ്ഷനുകളും സംരക്ഷിക്കലും API വഴിയാണ്; സംഗ്രഹം ചികിത്സാ നിർദേശമല്ല.",
  "template.triage.guideRecovery": "ഡ്രാഫ്റ്റുകൾ APIയിൽ സേവ് ചെയ്യാം; രോഗിയെ വീണ്ടും തുറക്കുമ്പോൾ ലഭിക്കും. പിശകുകളിൽ വിവരങ്ങൾ നിലനിൽക്കും; വീണ്ടും ശ്രമിക്കുമ്പോൾ അതേ പ്രവർത്തന ഐഡി ഉപയോഗിക്കും. തർക്കമുണ്ടെങ്കിൽ പുതിയത് ലോഡ് ചെയ്യുക; പൂർത്തിയായ സർവർ രേഖ പഴയ മാറ്റങ്ങളെ മാറ്റിസ്ഥാപിക്കും, പുനർവിലയിരുത്തൽ വേറെയായി നടത്തണം.",
  "template.triage.guideLimits": "ഇത് സാങ്കൽപ്പിക വിവരശേഖരണ പ്രവാഹമാണ്; സാധൂകരിച്ച ട്രയേജ് സ്കെയിലോ ക്ലിനിക്കൽ സ്കോറോ ചികിത്സാ നിർദേശമോ അല്ല. മുൻഗണന നേരിട്ട് നൽകണം. പ്രോട്ടോകോളുകൾ, ക്ലിനിക്കൽ പരിശോധന, നഴ്സ് അനുമതികൾ, സൂക്ഷിക്കൽ നയങ്ങൾ എന്നിവ ബന്ധിപ്പിക്കുന്ന ആപ്പിന്റെ ഉത്തരവാദിത്തമാണ്.",
  "template.consultation.title": "ക്ലിനിക്കൽ കൺസൾട്ടേഷൻ",
  "template.consultation.subtitle": "ക്ലിനിക്കൽ ചരിത്രം, വിലയിരുത്തൽ, പരിചരണ പദ്ധതി.",
