  "template.consultation.confirmHint": "രോഗി, സന്ദർശനം, ഡോക്ടർ, വിലയിരുത്തൽ, പദ്ധതി എന്നിവ പരിശോധിക്കുക. പൂർത്തിയാക്കിയ കുറിപ്പ് ലോക്ക് ചെയ്യും; തുടർപരിചരണത്തിന് പുതിയ കൺസൾട്ടേഷൻ ഉപയോഗിക്കുക.",
  "template.consultation.discardTitle": "സേവ് ചെയ്യാത്ത മാറ്റങ്ങൾ ഉപേക്ഷിക്കണോ?",
  "template.consultation.discardHint": "മാറ്റങ്ങൾ നിലനിർത്താൻ ഡ്രാഫ്റ്റ് സേവ് ചെയ്യുക. തുടരുമ്പോൾ സേവ് ചെയ്യാത്ത വിവരങ്ങൾ മാത്രം നഷ്ടപ്പെടും; സേവ് ചെയ്ത വിലയിരുത്തലുകൾ ലഭ്യമാകും.",
