  "template.consultation.choosePatient": "കൺസൾട്ടേഷൻ തുടങ്ങാൻ രോഗിയെ കണ്ടെത്തി തിരഞ്ഞെടുക്കുക.",
  "template.consultation.required": "ട്രയേജ് പൂർത്തിയാക്കുന്നതിന് മുമ്പ് ഈ വിവരം നൽകുക.",
  "template.consultation.invalid": "നൽകിയ മൂല്യം പരിശോധിക്കുക.",
  "template.consultation.denied": "ട്രയേജ് കൺസൾട്ടേഷൻ സേവ് ചെയ്യാൻ അനുമതിയില്ല.",
  "template.consultation.conflict": "ഈ കൺസൾട്ടേഷൻ മാറി. പുതിയത് ലോഡ് ചെയ്ത് വീണ്ടും സേവ് ചെയ്യുന്നതിന് മുമ്പ് പരിശോധിക്കുക.",
  "template.consultation.completedLocked": "പൂർത്തിയായ വിലയിരുത്തലുകൾ ലോക്ക് ചെയ്തിരിക്കുന്നു. മാറ്റങ്ങൾ രേഖപ്പെടുത്താൻ പുതിയത് തുടങ്ങുക.",
  "template.consultation.notFound": "കൺസൾട്ടേഷൻ കണ്ടെത്തിയില്ല.",
  "template.consultation.storage": "കൺസൾട്ടേഷൻ സേവ് ചെയ്യാനായില്ല. വീണ്ടും ശ്രമിക്കാൻ വിവരങ്ങൾ നിലനിൽക്കുന്നു.",
  "template.consultation.event.saved": "ഡ്രാഫ്റ്റ് ഡെമോ APIയിൽ സേവ് ചെയ്തു",
  "template.consultation.event.completed": "ട്രയേജ് കൺസൾട്ടേഷൻ പൂർത്തിയായി",
  "template.consultation.guideFlow": "രോഗി, സന്ദർശനം, ഡോക്ടർ, സന്ദർശന തരം എന്നിവ തിരഞ്ഞെടുക്കുക. ചരിത്രം, പരിശോധന, വിലയിരുത്തൽ, പദ്ധതി എന്നിവ നൽകുക. ഡ്രാഫ്റ്റ് സേവ് ചെയ്യുക അല്ലെങ്കിൽ പരിശോധിച്ച് പൂർത്തിയാക്കുക. പഴയ കൺസൾട്ടേഷനുകളിൽ നിന്ന് ഡ്രാഫ്റ്റോ പൂർത്തിയായ കുറിപ്പോ തുറക്കാം.",
  "template.consultation.guideIntegration": "ClinicalConsultationWorkspace ടൈപ്പ് ചെയ്ത കൺസൾട്ടേഷൻ, രോഗി അഡാപ്റ്ററുകളുമായി ബന്ധിപ്പിക്കുക. അംഗീകൃത അഭ്യർത്ഥനകൾ രോഗിയുടെ CSV വായിക്കുകയും ടെനന്റ്, ആപ്ലിക്കേഷൻ, രോഗി അനുസരിച്ചുള്ള പ്രത്യേക CSV-യിൽ കുറിപ്പുകൾ സേവ് ചെയ്യുകയും ചെയ്യുന്നു.",
  "template.consultation.guidePreferences": "റെയിലിൽ മൂന്ന് ഗ്രൂപ്പുകൾ ഒരുമിച്ച് കാണാം. ടാബുകളും വിസാർഡും ഓരോ ഗ്രൂപ്പ് കാണിക്കും. തീം, ഫോണ്ട്, കോണുകൾ, ഭാഷ, ഷോർട്ട്കട്ടുകൾ, പട്ടിക എന്നിവ പ്രാബല്യത്തിലുള്ള ടെനന്റ് മുൻഗണനകൾ പിന്തുടരും.",
  "template.consultation.guideRecovery": "രോഗിയെ വീണ്ടും തുറക്കുമ്പോൾ API ഡ്രാഫ്റ്റ് ലഭിക്കും. വീണ്ടെടുക്കാവുന്ന പിശകുകളിൽ നൽകിയ വിവരങ്ങളും റിട്രൈ ഐഡിയും നിലനിൽക്കും. പഴയ പതിപ്പ് വീണ്ടും ലോഡ് ചെയ്ത് പരിശോധിച്ച് സേവ് ചെയ്യുക. പൂർത്തിയായ കുറിപ്പുകൾ വായിക്കാൻ മാത്രം.",
  "template.consultation.guideLimits": "സാങ്കൽപ്പിക രേഖപ്പെടുത്തൽ പ്രവാഹം. രോഗനിർണയ നിർദ്ദേശം, മരുന്ന് നിർദ്ദേശിക്കൽ, പരിശോധന അയയ്ക്കൽ, അപ്പോയിന്റ്മെന്റ്, ബില്ലിംഗ്, ഇലക്ട്രോണിക് ഒപ്പ്, ക്ലിനിക്കൽ തീരുമാന സഹായം എന്നിവ നടത്തുന്നില്ല. ക്ലിനിക്കൽ അവലോകനവും യഥാർത്ഥ EHR സംയോജനവും ആപ്ലിക്കേഷന്റെ ഉത്തരവാദിത്തമാണ്.",
  "template.consultation.historySection": "ചരിത്രവും സന്ദർശനവും",
