  "template.consultation.education": "രോഗിയുടെ ബോധവൽക്കരണം / കൗൺസലിംഗ്",
  "template.consultation.consentNotes": "സമ്മത ചർച്ച (കുറിപ്പുകൾ മാത്രം)",
  "template.consultation.functionalStatus": "പ്രവർത്തനശേഷി / പിന്തുണ ആവശ്യങ്ങൾ",
  "template.consultation.expanded.vitalsHint": "നിരീക്ഷിച്ച അളവുകളും സമയവും നൽകുക. സാധാരണ മൂല്യങ്ങൾ മുൻകൂട്ടി നൽകുന്നില്ല; ട്രയാജ് ഇറക്കുമതിയോ സ്കോർ കണക്കാക്കലോ ഇല്ല.",
  "template.consultation.guideExpanded": "മൂന്ന് കോളങ്ങളിലെ ഒറ്റ ക്ലിക്ക് ടാബുകൾ വഴി പന്ത്രണ്ട് വിഭാഗങ്ങൾ തുറക്കാം: സന്ദർശനം, പശ്ചാത്തലം, ജീവസൂചകങ്ങൾ, അലർജി, വിലയിരുത്തൽ, അവയവങ്ങൾ, ഫലങ്ങൾ, നടപടികൾ, പദ്ധതി, മരുന്നുകൾ, റഫറലുകൾ, ബോധവൽക്കരണം. സംഖ്യകൾ നൽകിയ ഫീൽഡുകൾ കാണിക്കുന്നു; വിഭാഗം മാറുമ്പോൾ വിവരങ്ങൾ നിലനിൽക്കും. പുതിയ ഐച്ഛിക ഫീൽഡുകൾ ഡെമോ API വഴി സേവ് ചെയ്യും; പഴയ കുറിപ്പുകൾ വായിക്കാം. ജീവസൂചകങ്ങൾ നേരിട്ട് നൽകണം. മരുന്ന്, നടപടി, റഫറൽ, സമ്മതം എന്നിവ രേഖപ്പെടുത്തൽ കുറിപ്പുകളാണ്; അയച്ചതോ ഒപ്പിട്ടതോ ആയ പ്രവർത്തനങ്ങളല്ല.",
  "template.op.title": "ഒപി കൺസൾട്ടേഷൻ",
  "template.op.subtitle": "ബാഹ്യരോഗി പ്രവർത്തനസ്ഥലം · ക്ലിനിക്കൽ പശ്ചാത്തലം, കുറിപ്പുകൾ, അവലോകനം.",
