  "template.op.readiness": "പൂർത്തിയായ നിർബന്ധിത രേഖാ ഫീൽഡുകൾ; ഇത് ക്ലിനിക്കൽ സ്കോർ അല്ല.",
  "template.op.notRecorded": "രേഖപ്പെടുത്തിയിട്ടില്ല",
  "template.op.review": "മുഴുവൻ കുറിപ്പ് പരിശോധിക്കുക",
  "template.op.reviewHint": "സേവ് ചെയ്യാത്ത വിവരങ്ങൾ ഉൾപ്പെടെയുള്ള കുറിപ്പിന്റെ വായനാ കാഴ്ച. പൂർത്തിയാക്കൽ വേറെ നടപടിയാണ്.",
  "template.op.triage": "അവസാനം പൂർത്തിയായ ട്രയാജ്",
  "template.op.noTriage": "പൂർത്തിയായ ട്രയാജ് ലഭ്യമല്ല.",
  "template.op.contextHint": "സൂചനയ്ക്ക് മാത്രം · ട്രയാജ് ഈ കൺസൾട്ടേഷനിലേക്ക് പകർത്തുന്നില്ല.",
  "template.consultation.guideOP": "ഒപി കൺസൾട്ടേഷനും ക്ലിനിക്കൽ കൺസൾട്ടേഷനും സേവ് ചെയ്ത കുറിപ്പുകൾ പങ്കിടുന്നു. വിഭാഗം തിരഞ്ഞെടുത്ത് ഫോം പൂരിപ്പിച്ച് സംഗ്രഹം പരിശോധിക്കുക. സംഗ്രഹത്തിലെ ബട്ടണുകൾ ബന്ധപ്പെട്ട വിഭാഗം തുറക്കും. മുഴുവൻ കുറിപ്പ് കാണുന്നത് സേവ് ചെയ്യില്ല. രോഗിയുടെ ബാനറിൽ ഡെമോ APIയിലെ അവസാനം പൂർത്തിയായ ട്രയാജ് സൂചനയായി കാണിക്കും; എല്ലാ അളവുകളും കാണാൻ വിശദാംശങ്ങൾ തുറക്കുക. ട്രയാജ് അതിന്റെ യഥാർത്ഥ സന്ദർശനത്തിന്റേതാണ്; സ്വയം പകർത്തില്ല.",
  "template.op.refreshTriage": "ട്രയാജ് പുതുക്കുക",
