  "template.comprehensive.actor": "രേഖപ്പെടുത്തിയത്",
  "template.comprehensive.open": "കൺസൾട്ടേഷൻ തുറക്കുക",
  "template.comprehensive.confirmHint": "നിങ്ങളുടെ ആധികാരിക അക്കൗണ്ടിൽ ഡെമോ രേഖ അന്തിമമാക്കുക. തുടർന്ന് വായിക്കാൻ മാത്രം കഴിയും. ഓർഡറുകൾ അയയ്ക്കുകയോ അംഗീകൃത ഡിജിറ്റൽ ഒപ്പ് സൃഷ്ടിക്കുകയോ ഇല്ല.",
  "template.comprehensive.discardTitle": "സേവ് ചെയ്യാത്ത മാറ്റങ്ങൾ ഉപേക്ഷിക്കണോ?",
  "template.comprehensive.discardHint": "മാറ്റങ്ങൾ നിലനിർത്താൻ ഡ്രാഫ്റ്റ് സേവ് ചെയ്യുക. തുടരുമ്പോൾ സേവ് ചെയ്യാത്ത വിവരങ്ങൾ മാത്രം നഷ്ടപ്പെടും; സേവ് ചെയ്ത വിലയിരുത്തലുകൾ ലഭ്യമാകും.",
  "template.comprehensive.demo": "സാങ്കൽപ്പിക കൺസൾട്ടേഷൻ · ഡെമോ സംയോജനങ്ങൾ",
  "template.comprehensive.choosePatient": "കൺസൾട്ടേഷൻ തുടങ്ങാൻ രോഗിയെ കണ്ടെത്തി തിരഞ്ഞെടുക്കുക.",
  "template.comprehensive.required": "ട്രയേജ് പൂർത്തിയാക്കുന്നതിന് മുമ്പ് ഈ വിവരം നൽകുക.",
  "template.comprehensive.invalid": "നൽകിയ മൂല്യം പരിശോധിക്കുക.",
  "template.comprehensive.denied": "ഈ കൺസൾട്ടേഷൻ സേവ് ചെയ്യാൻ അനുമതിയില്ല.",
  "template.comprehensive.conflict": "ഈ കൺസൾട്ടേഷൻ മാറി. പുതിയത് ലോഡ് ചെയ്ത് വീണ്ടും സേവ് ചെയ്യുന്നതിന് മുമ്പ് പരിശോധിക്കുക.",
  "template.comprehensive.completedLocked": "പൂർത്തിയായ വിലയിരുത്തലുകൾ ലോക്ക് ചെയ്തിരിക്കുന്നു. മാറ്റങ്ങൾ രേഖപ്പെടുത്താൻ പുതിയത് തുടങ്ങുക.",
  "template.comprehensive.notFound": "കൺസൾട്ടേഷൻ കണ്ടെത്തിയില്ല.",
  "template.comprehensive.storage": "കൺസൾട്ടേഷൻ സേവ് ചെയ്യാനായില്ല. വീണ്ടും ശ്രമിക്കാൻ വിവരങ്ങൾ നിലനിൽക്കുന്നു.",
  "template.comprehensive.event.saved": "ഡ്രാഫ്റ്റ് ഡെമോ APIയിൽ സേവ് ചെയ്തു",
  "template.comprehensive.event.completed": "ഡെമോ കൺസൾട്ടേഷനിൽ ഒപ്പിട്ടു",
  "template.comprehensive.guideFlow": "രോഗിയും സന്ദർശനവും തിരഞ്ഞെടുക്കുക, കൺസൾട്ടേഷൻ രേഖപ്പെടുത്തുക, രോഗനിർണയങ്ങളും ഓർഡറുകളും ചേർക്കുക, മുഴുവൻ രേഖയും പരിശോധിച്ച് സ്ഥിരീകരിച്ച് ഡെമോ രേഖയിൽ ഒപ്പിടുക.",
  "template.comprehensive.guideIntegration": "ComprehensiveConsultationWorkspace-ൽ ആധികാരിക രോഗി, ട്രയാജ്, സമഗ്ര കൺസൾട്ടേഷൻ അഡാപ്റ്ററുകൾ നൽകുക. ക്രമീകരണങ്ങളും സേവനങ്ങളും ഡെമോ API-യിൽ നിന്നാണ്; രേഖകൾ പ്രത്യേക CSV-യിൽ സേവ് ചെയ്യുന്നു.",
  "template.comprehensive.guidePreferences": "പ്രത്യേക കൺസൾട്ടേഷൻ നാവിഗേറ്ററിനു പകരം നമ്പറുള്ള മാസ്റ്റർ റെക്കോർഡ് നാവിഗേഷൻ ഉപയോഗിക്കുന്നു. സംഗ്രഹത്തിനരികിൽ ഒരു വിഭാഗം തിരഞ്ഞെടുക്കുക; സ്ക്രോൾ റെക്കോർഡ് ഭാഗത്തിനുള്ളിലായിരിക്കും. ടാബുകളും വിസാർഡും മുൻഗണനകളും ടെനന്റ് ലോക്കുകളും പാലിക്കും. API രേഖ, ഓർഡർ, സ്കോർ, അവലോകനം, ഒപ്പ് പ്രവാഹങ്ങൾ തുടരും.",
  "template.comprehensive.guideRecovery": "രോഗിയെ വീണ്ടും തുറക്കുമ്പോൾ API ഡ്രാഫ്റ്റ് ലഭിക്കും. വീണ്ടെടുക്കാവുന്ന പിശകുകളിൽ നൽകിയ വിവരങ്ങളും റിട്രൈ ഐഡിയും നിലനിൽക്കും. പഴയ പതിപ്പ് വീണ്ടും ലോഡ് ചെയ്ത് പരിശോധിച്ച് സേവ് ചെയ്യുക. പൂർത്തിയായ കുറിപ്പുകൾ വായിക്കാൻ മാത്രം.",
  "template.comprehensive.guideLimits": "നിങ്ങളുടെ ആധികാരിക അക്കൗണ്ടിൽ ഡെമോ രേഖ അന്തിമമാക്കുക. തുടർന്ന് വായിക്കാൻ മാത്രം കഴിയും. ഓർഡറുകൾ അയയ്ക്കുകയോ അംഗീകൃത ഡിജിറ്റൽ ഒപ്പ് സൃഷ്ടിക്കുകയോ ഇല്ല. ഡെമോ പൂർണ്ണതാ പരിശോധനകൾ മാത്രം. പുറം പരിശോധനയ്ക്കും റിപ്പോർട്ടിംഗിനും അംഗീകൃത പതിപ്പുള്ള സംയോജനങ്ങൾ ആവശ്യമാണ്.",
