  "care.extra138": "വ്യത്യസ്ത സാധ്യതാ രോഗനിർണയങ്ങൾ",
  "care.help.overview": "പ്രാമാണീകരിച്ച ഡെമോ API-യും CSV രേഖകളും ഉപയോഗിച്ച് നൽകിയ ഡിസൈനുകൾ ഈ ഘടകാധിഷ്ഠിത പേജുകൾ അവതരിപ്പിക്കുന്നു.",
  "care.help.emergency": "രോഗിയെ തിരഞ്ഞെടുക്കുക അല്ലെങ്കിൽ താൽക്കാലിക തിരിച്ചറിയൽ സൃഷ്ടിക്കുക. അടിയന്തര സന്ദർശനം തുറന്ന് ട്രയാജ് രേഖപ്പെടുത്തി രജിസ്ട്രേഷനും പരിചരണവും പൂർത്തിയാക്കുക. പൂർത്തീകരണത്തിന് മുമ്പ് തുടർനടപടിയും കൈമാറ്റവും പരിശോധിക്കുക.",
  "care.help.inpatient": "രോഗിയും പ്രവേശന ഉറവിടവും തിരഞ്ഞെടുക്കുക. സ്വീകരിക്കുന്ന ടീമും കവറേജും രേഖപ്പെടുത്തി അനുയോജ്യമായ കിടക്ക റിസർവ് ചെയ്യുക. രോഗിയെ സ്ഥിരീകരിച്ച് പ്രവേശിപ്പിക്കുക. നഴ്സിംഗ്, വൈദ്യപരിചരണം, ഓർഡർ, മാറ്റം, ഡിസ്ചാർജ് ടാബുകളിൽ തുടരുക.",
  "care.help.consultation": "രോഗിയും കൺസൾട്ടേഷൻ ക്രമീകരണവും തിരഞ്ഞെടുക്കുക. വിഭാഗ നാവിഗേഷൻ ഉപയോഗിച്ച് ഏഴ് ചികിത്സാ വിഭാഗങ്ങൾ പൂർത്തിയാക്കുക. ഒപ്പിടുന്നതിന് മുമ്പ് സൂക്ഷിച്ച് പ്രിവ്യൂ പരിശോധിച്ച് സ്ഥിരീകരിക്കുക. ഒപ്പിട്ട രേഖകളിൽ തിരുത്തലിന് പകരം അനുബന്ധം ചേർക്കാം.",
  "care.help.orders": "രണ്ടാം പതിപ്പിൽ മരുന്ന്, ലാബ്, ഇമേജിംഗ്, പ്രൊസീജർ ഓർഡർ ഡയലോഗുകളുണ്ട്. എല്ലാ വിവരങ്ങളും API സൂക്ഷിക്കുന്നു. റദ്ദാക്കുമ്പോഴും യഥാർത്ഥ ഓർഡർ ചരിത്രത്തിൽ നിലനിൽക്കും.",
  "care.help.preferences": "തീം, ഫോണ്ട് അളവുകൾ, സാന്ദ്രത, ഫീൽഡ് അവതരണം, ഭാഷ, തീയതി രൂപം എന്നിവ മുൻഗണനകളും ടെനന്റ് ലോക്കുകളും അനുസരിക്കുന്നു. ഈ പേജുകൾക്ക് വേറെ ആപ്ലിക്കേഷൻ സൈഡ്ബാർ ഇല്ല.",
  "care.help.recovery": "ഡ്രാഫ്റ്റ് സൂക്ഷിക്കൽ API രേഖ എഴുതുന്നു. സൂക്ഷിച്ച രേഖയുടെ പട്ടികയിൽ നിന്ന് വീണ്ടെടുക്കാം. പരാജയത്തിൽ മൂല്യങ്ങൾ നിലനിൽക്കും; വീണ്ടും ശ്രമിക്കുമ്പോൾ അതേ ഓപ്പറേഷൻ ID ഉപയോഗിക്കും. സംഘർഷത്തിനുശേഷം സ്ഥിരീകരിച്ചാൽ മാത്രമേ വീണ്ടും ലോഡ് ചെയ്യുന്നത് തിരുത്തലുകൾ മാറ്റൂ.",
  "care.help.boundary": "ഇത് പുനരുപയോഗിക്കാവുന്ന ഫ്രണ്ട്എൻഡ് ഡെമോയാണ്, യഥാർത്ഥ ചികിത്സാ സംവിധാനമല്ല. പണമടയ്ക്കുന്ന സ്ഥാപനത്തിന്റെ സ്ഥിരീകരണം, യഥാർത്ഥ മാറ്റം, കിടക്ക വൃത്തിയാക്കൽ, മരുന്ന് കുറിപ്പടി, നിയമപരമായ ഒപ്പ് എന്നിവയ്ക്ക് വേറെ സംയോജനങ്ങൾ ആവശ്യമാണ്. യഥാർത്ഥ രോഗിവിവരങ്ങൾ നൽകരുത്.",
  "care.help.integration": "CareWorkspace-ലേക്ക് createCareAdapter-ഉം പ്രാബല്യത്തിലുള്ള മുൻഗണന ഹോസ്റ്റും നൽകുക. പ്രാമാണീകരിച്ച POST /care-pages ടെനന്റ്, ആപ്ലിക്കേഷൻ, ഉപയോക്താവ്, പേജ് എന്നിവയനുസരിച്ച് രേഖകൾ വേർതിരിക്കുന്നു. നിർവചനങ്ങളും സാങ്കൽപ്പിക രോഗികളും കിടക്കകളും ബാക്ക്എൻഡിലെ JSON, CSV ഫയലുകളിൽ നിന്നാണ്.",
