  "designer.catalogPinned": "ഫോമുകൾ തിരഞ്ഞെടുത്ത പതിപ്പ് ഉപയോഗിക്കുന്നു. കാറ്റലോഗിന്റെ പുതിയ പതിപ്പ് സൂക്ഷിക്കുന്നത് നിലവിലുള്ള ഫോമുകൾ മാറ്റില്ല.",
