  "designer.catalogSaved": "പുതിയ പതിപ്പ് സൂക്ഷിച്ചു. നിലവിലുള്ള ഫോമുകളുടെ അവലംബങ്ങൾ മാറിയിട്ടില്ല.",
  "designer.catalogInvalid": "ഒരു പേരും തനതായ ഓപ്ഷനുകളും നൽകുക, അല്ലെങ്കിൽ തിരഞ്ഞെടുത്ത പതിപ്പുകളിൽ ഓരോ അനുബന്ധ ഓപ്ഷനും സാധുവായ മാതൃ മൂല്യവുമായി ബന്ധിപ്പിക്കുക.",
  "designer.catalogCountryState": "രാജ്യം → സംസ്ഥാനം",
  "designer.catalogRefresh": "കാറ്റലോഗ് പുതുക്കുക",
  "designer.catalogRefreshed": "കാറ്റലോഗ് പുതുക്കി. ഏറ്റവും പുതിയ മൂല്യങ്ങൾ തിരുത്താൻ പതിപ്പ് വീണ്ടും തുറക്കുക; നിലവിലെ തിരുത്തലുകൾ ഇവിടെ നിലനിൽക്കുന്നു.",
  "designer.help.catalog": "നിലവിലെ ടെനന്റിലും ആപ്ലിക്കേഷനിലും പങ്കിടുന്ന ഓപ്ഷൻ പട്ടികകൾ സൃഷ്ടിക്കാൻ മൂല്യസമുച്ചയങ്ങൾ നിയന്ത്രിക്കുക തുറക്കുക. അഡ്മിനിസ്ട്രേറ്റർമാർക്ക് മാത്രമേ പുതിയ പതിപ്പുകൾ സൂക്ഷിക്കാനാകൂ. ബന്ധങ്ങളിൽ മാതൃ-അനുബന്ധ സമുച്ചയങ്ങളുടെ കൃത്യമായ പതിപ്പുകൾ തിരഞ്ഞെടുത്ത് ഓരോ അനുബന്ധ ഓപ്ഷനും ബന്ധിപ്പിക്കുക. ഫീൽഡ് സജ്ജീകരണത്തിൽ ഓപ്ഷൻ ഉറവിടത്തിന്റെ പതിപ്പ് തിരഞ്ഞെടുക്കുക; ആശ്രിത ഫീൽഡിന് മാതൃ ഫീൽഡും അനുയോജ്യമായ പങ്കിട്ട ബന്ധവും തിരഞ്ഞെടുക്കണം. പുതിയ പതിപ്പ് സൂക്ഷിക്കുമ്പോൾ നിലവിലുള്ള ഫോമുകൾ പഴയ പതിപ്പിൽ തുടരും. പുതിയ പതിപ്പ് സ്വീകരിക്കാൻ വ്യക്തമായ തിരഞ്ഞെടുപ്പ് വേണം. കാറ്റലോഗ് പുതുക്കുന്നത് തിരുത്തലുകൾ നിലനിർത്തും; വൈരുദ്ധ്യത്തിന് ശേഷം സൂക്ഷിക്കുന്നതിന് മുമ്പ് ഏറ്റവും പുതിയ പതിപ്പ് വീണ്ടും തുറക്കുക. കാറ്റലോഗ് മാറ്റങ്ങൾ നിലവിലെ ഫോം സൂക്ഷിക്കുകയോ മാറ്റിസ്ഥാപിക്കുകയോ ചെയ്യില്ല. ഫോമിനുള്ളിലെ ഓപ്ഷനുകളും പിന്തുണയ്ക്കുന്നു. ഓരോ സമുച്ചയത്തിലും 50 ഓപ്ഷനുകളും സമുച്ചയങ്ങൾക്കും ബന്ധങ്ങൾക്കും പ്രത്യേകം 100 പതിപ്പുകളും അനുവദനീയമാണ്. പ്രൊഡക്ഷൻ DCP സംയോജനം, പ്രവർത്തനരഹിത മൂല്യങ്ങളുടെ നയങ്ങൾ, പ്രസിദ്ധീകരണ അംഗീകാരങ്ങൾ എന്നിവ പൂർത്തിയായിട്ടില്ല.",
  "designer.catalogLimit": "ഈ എൻട്രി തരത്തിനായി കാറ്റലോഗ് 100 പതിപ്പുകളുടെ പരിധിയിലെത്തി.",
  "designer.csvImport": "CSV ഓപ്ഷനുകൾ ഇറക്കുമതി ചെയ്യുക",
  "designer.csvHelp": "UTF-8 CSV അപ്‌ലോഡ് ചെയ്ത് ഐഡി, ലേബൽ കോളങ്ങൾ തിരഞ്ഞെടുത്ത് എല്ലാ വരികളും പരിശോധിക്കുക. പ്രയോഗിക്കുന്നത് ഓപ്ഷൻ എഡിറ്റർ മാത്രം മാറ്റുന്നു; പുതിയ പതിപ്പ് സേവ് ചെയ്യുമ്പോൾ മുഴുവൻ ഡാറ്റാസെറ്റും API വഴി സേവ് ചെയ്യുന്നു. പഴയ റഫറൻസുകൾ മാറില്ല.",
