  "designer.csvMapping": "ഐഡിക്കും ലേബലിനും വ്യത്യസ്ത കോളങ്ങൾ തിരഞ്ഞെടുക്കുക.",
  "designer.csvRow": "ശൂന്യമല്ലാത്ത തനതായ ഐഡി (80 അക്ഷരം വരെ), ലേബൽ (160 വരെ) നൽകുക. പൈപ്പ് ചിഹ്നവും വരി വിഭജനവും ഈ എഡിറ്ററിൽ പിന്തുണയ്ക്കുന്നില്ല.",
