  "designer.lifecycleHelp": "ഡെമോ അഡ്മിൻ അവലോകനവും പ്രസിദ്ധീകരണവും പരീക്ഷിക്കുന്നു. ഉൽപ്പാദനത്തിലെ ചുമതല വേർതിരിവിന് ഹോസ്റ്റ് അനുമതി/വർക്ക്ഫ്ലോ വേണം. മാറ്റങ്ങൾ ആദ്യം സേവ് ചെയ്യുക.",
