  "designer.datasetHelp": "CSV അല്ലെങ്കിൽ XLSX അപ്‌ലോഡ് ചെയ്ത് ഷീറ്റും ടെക്സ്റ്റ് ഐഡി/ലേബൽ കോളങ്ങളും തിരഞ്ഞെടുക്കുക. എഡിറ്റർ മാറ്റും മുമ്പ് എല്ലാ വരികളും പരിശോധിക്കുക. സേവ് ചെയ്യുന്നത് ഒരു പൂർണ്ണ പതിപ്പാണ്; പഴയ റഫറൻസുകൾ മാറില്ല.",
