  "designer.v1.conflict": "വീണ്ടും ലോഡ് ചെയ്യുമ്പോൾ സംരക്ഷിക്കാത്ത മാറ്റങ്ങൾ നഷ്ടപ്പെടും. വൈരുദ്ധ്യമോ സംരക്ഷണത്തിലെ അനിശ്ചിതത്വമോ ഉണ്ടായാൽ ഏറ്റവും പുതിയ രേഖ പരിശോധിക്കുക. സ്വയം വീണ്ടും സംരക്ഷിക്കില്ല.",
