  "designer.multiParentHelp": "എല്ലാ പേരന്റ് തിരഞ്ഞെടുപ്പുകളും പൊരുത്തപ്പെടണം. ഏതെങ്കിലും പേരന്റ് മാറ്റിയാൽ ഈ ഫീൽഡും ആശ്രിത ഫീൽഡുകളും മായ്ക്കും.",
