  "designer.compareRelease": "പതിപ്പുമായി താരതമ്യം ചെയ്യുക",
  "designer.compareHelp": "പ്രസിദ്ധീകരിക്കുന്നതിന് മുമ്പ് സ്ഥിരമായ ഫീൽഡ് തിരിച്ചറിയൽ പ്രകാരം മാറ്റങ്ങൾ പരിശോധിക്കുക. താഴെയുള്ളവ ഡിസൈൻ മെറ്റാഡാറ്റയാണ്, രോഗിയുടെ ഉത്തരങ്ങളല്ല.",
