  "lifecycle.unavailable": "ലൈഫ്സൈക്കിൾ കോൺഫിഗറേഷൻ ഇവിടെ പ്രവർത്തനക്ഷമമാക്കിയിട്ടില്ല",
  "lifecycle.unavailableHelp": "ഈ ആപ്ലിക്കേഷൻ ലൈഫ്സൈക്കിൾ അഡ്മിനിസ്ട്രേഷൻ പ്രവർത്തനക്ഷമമാക്കിയിട്ടില്ല. അത് പ്രവർത്തനക്ഷമമാക്കുന്നതുവരെ നിർവചനങ്ങളൊന്നും കാണിക്കില്ല.",
  "lifecycle.unavailableSchema": "ഈ ടെനന്റിനായി ലൈഫ്സൈക്കിൾ സംഭരണം തയ്യാറാക്കിയിട്ടില്ല. അത് തയ്യാറാകുന്നതുവരെ നിർവചനങ്ങളൊന്നും കാണിക്കില്ല.",
