  "lifecycle.error.REASON_NOT_TRANSMITTABLE": "ഈ ആപ്ലിക്കേഷന് മാറ്റത്തിന്റെ കാരണങ്ങൾ ലാറ്റിൻ അക്ഷരങ്ങളിലും വരിമുറിവുകളില്ലാതെയും മാത്രമേ രേഖപ്പെടുത്താനാകൂ. കാരണം മാറ്റിയെഴുതി വീണ്ടും ശ്രമിക്കുക.",
