  "lifecycle.error.REASON_INVALID_CHARACTERS": "മാറ്റത്തിന്റെ കാരണത്തിൽ വരിമുറിവുകളോ മറ്റ് നിയന്ത്രണ അക്ഷരങ്ങളോ ഉണ്ട്. അവ നീക്കം ചെയ്ത് വീണ്ടും ശ്രമിക്കുക.",
  "lifecycle.host.title": "ഇൻസ്റ്റാൾ ചെയ്ത കഴിവുകൾ",
