  "lifecycle.section.sourceMappings": "സോഴ്സ് മാപ്പിംഗുകൾ",
  "lifecycle.help.sourceMappings": "രജിസ്റ്റർ ചെയ്ത ഒരു ആപ്ലിക്കേഷൻ സോഴ്സിലെ പ്രവർത്തനത്തെ ലൈഫ്സൈക്കിളിൽ പ്രഖ്യാപിച്ച ഒരു ഘട്ട ഇവന്റുമായി ബന്ധിപ്പിക്കുക, ഇവന്റ് പേലോഡിൽ ഉൾപ്പെടുത്തേണ്ട അനുവദനീയമായ സോഴ്സ് ഫീൽഡുകൾ തിരഞ്ഞെടുക്കുക. മാപ്പിംഗുകൾ ഈ ഡ്രാഫ്റ്റിൽ സംരക്ഷിക്കപ്പെടുകയും അതിന്റെ അംഗീകാരം, പ്രസിദ്ധീകരണം, സജീവമാക്കൽ എന്നിവ പിന്തുടരുകയും ചെയ്യുന്നു.",
  "lifecycle.source.showRegistry": "സോഴ്സ് രജിസ്ട്രി കാണിക്കുക",
  "lifecycle.source.hideRegistry": "സോഴ്സ് രജിസ്ട്രി മറയ്ക്കുക",
  "lifecycle.source.registry.title": "സോഴ്സ് രജിസ്ട്രി",
  "lifecycle.source.registry.help": "{application} അതിന്റെ സജീവവും പിൻ ചെയ്തതുമായ സോഴ്സ് മെറ്റാഡാറ്റ റിലീസിൽ രജിസ്റ്റർ ചെയ്ത സോഴ്സുകൾ. ഈ കാഴ്ച സ്കീമ മെറ്റാഡാറ്റ മാത്രമേ കാണിക്കൂ; റെക്കോർഡ് മൂല്യങ്ങൾ ഒരിക്കലും കാണിക്കുന്നില്ല, ഡാറ്റ ആക്സസ് നൽകുന്നുമില്ല.",
  "lifecycle.source.loading": "സോഴ്സ് രജിസ്ട്രി ലോഡ് ചെയ്യുന്നു",
  "lifecycle.source.loadingHelp": "ഹോസ്റ്റിൽ നിന്ന് സോഴ്സ് ശേഷികളും രജിസ്റ്റർ ചെയ്ത സോഴ്സുകളും വായിക്കുന്നു.",
  "lifecycle.source.loadingDetail": "സോഴ്സ് വിശദാംശങ്ങൾ ലോഡ് ചെയ്യുന്നു…",
  "lifecycle.source.denied": "സോഴ്സ് രജിസ്ട്രിയിലേക്ക് പ്രവേശനം അനുവദനീയമല്ല",
  "lifecycle.source.deniedHelp": "നിങ്ങളുടെ അക്കൗണ്ടിന് ഈ ആപ്ലിക്കേഷന്റെ സോഴ്സ് രജിസ്ട്രി വായിക്കാൻ കഴിയില്ല. നിലവിലുള്ള മാപ്പിംഗുകൾ കാണാം, പക്ഷേ ഇവിടെ മാറ്റാൻ കഴിയില്ല.",
  "lifecycle.source.unavailable": "ഈ ഹോസ്റ്റിൽ സോഴ്സ് രജിസ്ട്രി പ്രവർത്തനക്ഷമമല്ല. ഇവിടെ സോഴ്സ് മാപ്പിംഗുകൾ ചേർക്കാനോ സ്ഥിരീകരിക്കാനോ കഴിയില്ല.",
  "lifecycle.source.empty": "രജിസ്റ്റർ ചെയ്ത സോഴ്സുകളൊന്നുമില്ല",
  "lifecycle.source.emptyHelp": "ഈ ആപ്ലിക്കേഷനായി അംഗീകരിച്ച് പിൻ ചെയ്ത സോഴ്സ് മെറ്റാഡാറ്റ ഹോസ്റ്റിനില്ല. സോഴ്സുകൾ രജിസ്റ്റർ ചെയ്യുന്നത് ആപ്ലിക്കേഷന്റെ സോഴ്സ് മെറ്റാഡാറ്റ റിലീസ് വഴിയാണ്, ഈ പേജിലല്ല.",
  "lifecycle.source.notConnected": "ഈ ഹോസ്റ്റ് ഒരു സോഴ്സ് രജിസ്ട്രി ബന്ധിപ്പിച്ചിട്ടില്ല. നിലവിലുള്ള സോഴ്സ് മാപ്പിംഗുകൾ വായിക്കാൻ മാത്രമായി കാണിക്കുന്നു.",
  "lifecycle.source.notRegistered": "ഈ സോഴ്സ് സജീവമായ പിൻ ചെയ്ത റിലീസിൽ രജിസ്റ്റർ ചെയ്തിട്ടില്ല. സോഴ്സ് വീണ്ടും രജിസ്റ്റർ ചെയ്യുകയോ മാപ്പിംഗ് നീക്കം ചെയ്യുകയോ ചെയ്യുന്നതുവരെ മാപ്പിംഗ് സജീവമാക്കാൻ കഴിയില്ല.",
