  "lifecycle.source.noTableSlots": "ഈ ടേബിൾ ക്യാപ്ചർ പുറപ്പെടുവിക്കുന്ന ഇവന്റ് തരവും സ്കീമ പതിപ്പുമായി പൊരുത്തപ്പെടുന്ന പ്രഖ്യാപിത ഘട്ട ഇവന്റൊന്നുമില്ല.",
