  "lifecycle.source.fieldsHelpTable": "സജീവ ടേബിൾ ക്യാപ്ചർ പേലോഡിലെ കോളങ്ങൾ മാത്രമേ മാപ്പ് ചെയ്യാനാകൂ, ഓരോന്നും സ്വന്തം പേരിൽ പകർത്തുന്നു. നിയന്ത്രിത ട്രിഗർ ഇതിനകം പിടിച്ചെടുക്കുന്നതിനപ്പുറം ഒന്നും വെളിപ്പെടുത്തുന്നില്ല.",
